# `groupBy` Utility Function

## Implementation

```javascript
/**
 * Groups an array of items into an object (or Map) where each key corresponds
 * to a group of items that share the same derived key value.
 *
 * @template T        - The type of items in the input array.
 * @template K        - The type of the derived key (string | number | symbol).
 *
 * @param {T[]} arr           - The array of items to group.
 * @param {(item: T, index: number, array: T[]) => K} keyFn
 *                            - A function called for each item that returns the
 *                              key under which the item should be grouped.
 *                              Receives the current item, its index, and the
 *                              original array (mirrors the Array#map signature).
 *
 * @returns {Record<K, T[]>}  - A plain object whose keys are the distinct values
 *                              returned by `keyFn` and whose values are arrays
 *                              of items that produced that key, in their original
 *                              order.
 *
 * @throws {TypeError} If `arr` is not an array.
 * @throws {TypeError} If `keyFn` is not a function.
 *
 * @example
 * // ── Group by a primitive property ──────────────────────────────────────────
 * const people = [
 *   { name: 'Alice', department: 'Engineering' },
 *   { name: 'Bob',   department: 'Design'      },
 *   { name: 'Carol', department: 'Engineering' },
 *   { name: 'Dave',  department: 'Design'      },
 *   { name: 'Eve',   department: 'HR'          },
 * ];
 *
 * groupBy(people, (p) => p.department);
 * // {
 * //   Engineering: [{ name: 'Alice', … }, { name: 'Carol', … }],
 * //   Design:      [{ name: 'Bob',   … }, { name: 'Dave',  … }],
 * //   HR:          [{ name: 'Eve',   … }],
 * // }
 *
 * @example
 * // ── Group numbers by even / odd ────────────────────────────────────────────
 * groupBy([1, 2, 3, 4, 5], (n) => (n % 2 === 0 ? 'even' : 'odd'));
 * // { odd: [1, 3, 5], even: [2, 4] }
 *
 * @example
 * // ── Use the index in the key function ─────────────────────────────────────
 * groupBy(['a', 'b', 'c', 'd'], (_, i) => (i < 2 ? 'first-half' : 'second-half'));
 * // { 'first-half': ['a', 'b'], 'second-half': ['c', 'd'] }
 *
 * @example
 * // ── Group by computed / transformed value ─────────────────────────────────
 * const words = ['apple', 'ant', 'banana', 'blueberry', 'cherry'];
 * groupBy(words, (w) => w[0].toUpperCase());
 * // { A: ['apple', 'ant'], B: ['banana', 'blueberry'], C: ['cherry'] }
 */
function groupBy(arr, keyFn) {
  // ── Guard clauses ────────────────────────────────────────────────────────────
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupBy: expected an array as the first argument, got ${typeof arr}`);
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(`groupBy: expected a function as the second argument, got ${typeof keyFn}`);
  }

  // ── Core reduction ───────────────────────────────────────────────────────────
  return arr.reduce((groups, item, index) => {
    const key = keyFn(item, index, arr);

    // Initialise the bucket on first encounter, then push.
    if (!Object.prototype.hasOwnProperty.call(groups, key)) {
      groups[key] = [];
    }
    groups[key].push(item);

    return groups;
  }, Object.create(null)); // null-prototype avoids collisions with inherited keys
}
```

