```javascript
/**
 * Identical to `groupBy` but returns a `Map<K, T[]>` instead of a plain object.
 *
 * Prefer this variant when:
 *  - Keys are objects, symbols, or any non-string type and you need them to
 *    remain un-coerced.
 *  - You need guaranteed insertion-order iteration (Maps always preserve it).
 *  - You want to avoid prototype-pollution concerns entirely.
 *
 * @template T
 * @template K
 *
 * @param {T[]} arr    - See `groupBy`.
 * @param {(item: T, index: number, array: T[]) => K} keyFn - See `groupBy`.
 * @returns {Map<K, T[]>}
 *
 * @example
 * const byLength = groupByMap(['one', 'two', 'three', 'four'], s => s.length);
 * byLength.get(3); // ['one', 'two']
 * byLength.get(5); // ['three']
 * byLength.get(4); // ['four']
 */
function groupByMap(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupByMap: expected an array as the first argument, got ${typeof arr}`);
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(`groupByMap: expected a function as the second argument, got ${typeof keyFn}`);
  }

  return arr.reduce((map, item, index) => {
    const key = keyFn(item, index, arr);

    if (!map.has(key)) {
      map.set(key, []);
    }
    map.get(key).push(item);

    return map;
  }, new Map());
}
