## Key Design Decisions

| Decision | Rationale |
|---|---|
| **`Object.create(null)`** | Avoids accidental collisions with `Object.prototype` properties like `toString`, `constructor`, or `hasOwnProperty` when those strings appear as keys. |
| **`hasOwnProperty` via `Object.prototype.call`** | Safe even on null-prototype objects, which lack the method directly. |
| **`keyFn(item, index, array)` signature** | Mirrors `Array.prototype.map` / `forEach` — familiar and allows index-aware grouping without extra wrappers. |
| **`groupByMap` companion** | Handles non-string keys (objects, symbols) without coercion, and is the right tool when key identity matters. |
| **No mutation of input** | Items are only read, never modified; the original array is untouched. |
| **Native `Array.groupBy` / `Object.groupBy`** | TC39 `Object.groupBy` reached Stage 4 (ES2024). This implementation is a polyfill-compatible drop-in for environments that lack it. |

# `groupBy` Utility Function

## Implementation

```javascript
/**
 * Groups an array of items into an object (or Map) where each key corresponds
 * to a group of items that share the same derived key value.
 *
 * @template T - The type of items in the input array.
 * @template K - The type of the derived key (must be a valid object key: string | number | symbol).
 *
 * @param {T[]} arr
 *   The array of items to group. Passing an empty array returns an empty object.
 *   Passing a non-array throws a TypeError.
 *
 * @param {(item: T, index: number, array: T[]) => K} keyFn
 *   A function called for every element in `arr`.
 *   It receives the same three arguments as `Array.prototype.map`:
 *     - `item`  – the current element
 *     - `index` – the element's index
 *     - `array` – the original array
 *   Its return value becomes the group key for that element.
 *   - Keys are coerced to strings when used as plain-object keys (standard JS behaviour).
 *   - If you need non-string keys (objects, Symbols, etc.) use the `{ useMap: true }` option.
 *
 * @param {{ useMap?: boolean }} [options={}]
 *   Optional configuration object.
 *   - `useMap` (default `false`): when `true`, returns a `Map<K, T[]>` instead of
 *     a plain `Record<string, T[]>`, preserving key types exactly.
 *
 * @returns {Record<string, T[]> | Map<K, T[]>}
 *   - Default: a plain object whose keys are the stringified group keys and whose
 *     values are arrays of items belonging to that group, in their original order.
 *   - With `useMap: true`: a `Map` with the same semantics but with exact key types.
 *
 * @throws {TypeError} If `arr` is not an array.
 * @throws {TypeError} If `keyFn` is not a function.
 *
 * @example
 * // ── Basic grouping ──────────────────────────────────────────────────────────
 * const people = [
 *   { name: 'Alice', dept: 'Engineering' },
 *   { name: 'Bob',   dept: 'Marketing'   },
 *   { name: 'Carol', dept: 'Engineering' },
 *   { name: 'Dave',  dept: 'Marketing'   },
 *   { name: 'Eve',   dept: 'Engineering' },
 * ];
 *
 * groupBy(people, (p) => p.dept);
 * // {
 * //   Engineering: [
 * //     { name: 'Alice', dept: 'Engineering' },
 * //     { name: 'Carol', dept: 'Engineering' },
 * //     { name: 'Eve',   dept: 'Engineering' },
 * //   ],
 * //   Marketing: [
 * //     { name: 'Bob',  dept: 'Marketing' },
 * //     { name: 'Dave', dept: 'Marketing' },
 * //   ],
 * // }
 *
 * @example
 * // ── Grouping numbers by remainder ───────────────────────────────────────────
 * groupBy([1, 2, 3, 4, 5, 6], (n) => n % 3);
 * // { '1': [1, 4], '2': [2, 5], '0': [3, 6] }
 *
 * @example
 * // ── Using the index parameter ────────────────────────────────────────────────
 * groupBy(['a', 'b', 'c', 'd'], (_, i) => (i % 2 === 0 ? 'even' : 'odd'));
 * // { even: ['a', 'c'], odd: ['b', 'd'] }
 *
 * @example
 * // ── Preserving key types with useMap ────────────────────────────────────────
 * const byLength = groupBy(['one', 'two', 'three', 'four'], (s) => s.length, { useMap: true });
 * // Map { 3 => ['one', 'two'], 5 => ['three'], 4 => ['four'] }
 * byLength.get(3); // ['one', 'two']
 */
function groupBy(arr, keyFn, { useMap = false } = {}) {
  // ── Guard clauses ────────────────────────────────────────────────────────────
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupBy: expected an array as the first argument, got ${typeof arr}`);
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(`groupBy: expected a function as the second argument, got ${typeof keyFn}`);
  }

  // ── Map variant ─────────────────────────────────────────────────────────────
  if (useMap) {
    const map = new Map();

    for (let i = 0; i < arr.length; i++) {
      const key = keyFn(arr[i], i, arr);

      if (map.has(key)) {
        map.get(key).push(arr[i]);
      } else {
        map.set(key, [arr[i]]);
      }
    }

    return map;
  }

  // ── Plain-object variant (default) ───────────────────────────────────────────
  // Object.create(null) avoids prototype pollution (no inherited keys like
  // 'constructor', 'toString', etc. accidentally matching a group key).
  const result = Object.create(null);

  for (let i = 0; i < arr.length; i++) {
    const key = keyFn(arr[i], i, arr);

    if (Object.prototype.hasOwnProperty.call(result, key)) {
      result[key].push(arr[i]);
    } else {
      result[key] = [arr[i]];
    }
  }

  return result;
}
```

