## Key Design Decisions

| Decision | Rationale |
|---|---|
| **`Object.create(null)`** | Eliminates prototype keys (`constructor`, `toString`, …) from ever colliding with a real group key |
| **`hasOwnProperty` check** | Safe even on null-prototype objects; avoids relying on `in` operator |
| **`useMap` option** | Lets callers preserve exact key types (numbers, Symbols, objects) without a separate function |
| **Same signature as `Array#map`** | `(item, index, array)` is familiar and enables index-based grouping without extra arguments |
| **Guard clauses with `TypeError`** | Fails fast with a clear message rather than silently returning wrong results |
| **No external dependencies** | Pure utility — zero-cost to add to any project |

# `groupBy` Utility Function

## Implementation

```javascript
/**
 * Groups an array of items into an object (or Map) where each key corresponds
 * to a group of items that share the same derived key value.
 *
 * @template T        - The type of elements in the input array.
 * @template K        - The type of the derived key (string | number | symbol).
 *
 * @param {T[]} arr
 *   The array of items to group. Passing an empty array returns an empty object.
 *   `null` / `undefined` values inside the array are forwarded to `keyFn` as-is.
 *
 * @param {(item: T, index: number, array: T[]) => K} keyFn
 *   A pure function that receives each element (plus its index and the original
 *   array, mirroring the signature of `Array.prototype.map`) and returns the
 *   key under which that element should be grouped.
 *
 *   Rules:
 *   - The function MUST return a value that is a valid object key
 *     (string, number, or symbol).
 *   - Returning `undefined` or `null` is allowed; those become the string
 *     keys `"undefined"` or `"null"` due to normal JS object coercion.
 *   - The function should be side-effect-free; it is called exactly once
 *     per element.
 *
 * @returns {Record<K, T[]>}
 *   A plain object whose own enumerable properties are the distinct keys
 *   produced by `keyFn`. Each property value is a non-empty array of items
 *   (in their original order) that mapped to that key.
 *
 * @throws {TypeError} If `arr` is not an array.
 * @throws {TypeError} If `keyFn` is not a function.
 *
 * @example
 * // ── Basic grouping by a property ──────────────────────────────────────────
 * const people = [
 *   { name: 'Alice', dept: 'Engineering' },
 *   { name: 'Bob',   dept: 'Marketing'   },
 *   { name: 'Carol', dept: 'Engineering' },
 * ];
 *
 * groupBy(people, p => p.dept);
 * // {
 * //   Engineering: [{ name: 'Alice', … }, { name: 'Carol', … }],
 * //   Marketing:   [{ name: 'Bob',   … }],
 * // }
 *
 * @example
 * // ── Grouping numbers by a computed property ────────────────────────────────
 * groupBy([1, 2, 3, 4, 5, 6], n => (n % 2 === 0 ? 'even' : 'odd'));
 * // { odd: [1, 3, 5], even: [2, 4, 6] }
 *
 * @example
 * // ── Using the index parameter ──────────────────────────────────────────────
 * groupBy(['a', 'b', 'c', 'd'], (_, i) => (i < 2 ? 'first-half' : 'second-half'));
 * // { 'first-half': ['a', 'b'], 'second-half': ['c', 'd'] }
 *
 * @example
 * // ── Grouping by a derived / transformed key ────────────────────────────────
 * const words = ['apple', 'avocado', 'banana', 'blueberry', 'cherry'];
 * groupBy(words, w => w[0].toUpperCase());
 * // { A: ['apple', 'avocado'], B: ['banana', 'blueberry'], C: ['cherry'] }
 */
function groupBy(arr, keyFn) {
  // ── Guard clauses ────────────────────────────────────────────────────────────
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupBy: expected an array as the first argument, got ${typeof arr}`);
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(`groupBy: expected a function as the second argument, got ${typeof keyFn}`);
  }

  // ── Core reduction ───────────────────────────────────────────────────────────
  return arr.reduce((groups, item, index) => {
    const key = keyFn(item, index, arr);

    // Initialise the bucket on first encounter, then push.
    // Using `Object.prototype.hasOwnProperty` avoids false positives when a
    // derived key happens to match an inherited property (e.g. "constructor").
    if (!Object.prototype.hasOwnProperty.call(groups, key)) {
      groups[key] = [];
    }

    groups[key].push(item);
    return groups;
  }, Object.create(null)); // null-prototype object avoids prototype pollution
}
