## Implementation

```javascript
/**
 * Groups an array of items into an object (map) where each key is derived
 * from a provided key function, and each value is an array of items that
 * share that key.
 *
 * @template T - The type of items in the input array.
 * @template K - The type of the derived key (must be a valid object key:
 *               string | number | symbol).
 *
 * @param {T[]} arr - The array of items to group. If empty, an empty object
 *                    is returned. Null/undefined items are included as-is and
 *                    grouped by whatever key the keyFn returns for them.
 * @param {function(item: T, index: number, array: T[]): K} keyFn - A function
 *   called for each item that returns the key under which the item should be
 *   grouped. Receives the same arguments as Array.prototype.map callbacks:
 *   the current item, its index, and the original array.
 *
 * @returns {Record<K, T[]>} A plain object whose keys are the distinct values
 *   returned by keyFn, and whose values are arrays of items (in their original
 *   order) that produced that key.
 *
 * @throws {TypeError} If `arr` is not an array.
 * @throws {TypeError} If `keyFn` is not a function.
 *
 * @example
 * // --- Group primitives ---
 * groupBy([1, 2, 3, 4, 5], n => (n % 2 === 0 ? 'even' : 'odd'));
 * // => { odd: [1, 3, 5], even: [2, 4] }
 *
 * @example
 * // --- Group objects by a property ---
 * const people = [
 *   { name: 'Alice', dept: 'Engineering' },
 *   { name: 'Bob',   dept: 'Marketing'   },
 *   { name: 'Carol', dept: 'Engineering' },
 * ];
 * groupBy(people, p => p.dept);
 * // => {
 * //   Engineering: [{ name: 'Alice', ... }, { name: 'Carol', ... }],
 * //   Marketing:   [{ name: 'Bob',   ... }],
 * // }
 *
 * @example
 * // --- Group by computed / transformed key ---
 * const words = ['apple', 'banana', 'avocado', 'blueberry', 'cherry'];
 * groupBy(words, w => w[0].toUpperCase());
 * // => { A: ['apple', 'avocado'], B: ['banana', 'blueberry'], C: ['cherry'] }
 *
 * @example
 * // --- Index receives the item's position ---
 * groupBy(['a', 'b', 'c', 'd'], (_, i) => (i < 2 ? 'first-half' : 'second-half'));
 * // => { 'first-half': ['a', 'b'], 'second-half': ['c', 'd'] }
 */
function groupBy(arr, keyFn) {
  // ── Guard clauses ────────────────────────────────────────────────────────
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupBy: expected an array as the first argument, got ${typeof arr}`);
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(`groupBy: expected a function as the second argument, got ${typeof keyFn}`);
  }

  // ── Core logic ───────────────────────────────────────────────────────────
  // Object.create(null) produces a truly empty object with no inherited
  // properties (no toString, hasOwnProperty, etc.), making it a safer map.
  return arr.reduce((groups, item, index) => {
    const key = keyFn(item, index, arr);

    // Initialise the bucket on first encounter, then push.
    if (!Object.prototype.hasOwnProperty.call(groups, key)) {
      groups[key] = [];
    }
    groups[key].push(item);

    return groups;
  }, Object.create(null));
}
