/**
 * Groups an array of items into an object (or Map) where each key corresponds
 * to a group of items that share the same derived key value.
 *
 * @template T - The type of items in the input array.
 * @template K - The type of the derived key (must be a valid object key: string | number | symbol).
 *
 * @param {T[]} arr - The array of items to group. Passing a non-array throws a TypeError.
 * @param {(item: T, index: number, array: T[]) => K} keyFn - A function called for each
 *   item that returns the key under which that item should be grouped.
 *   Receives the same arguments as Array.prototype.map's callback:
 *     - item  : the current element
 *     - index : the element's index
 *     - array : the original array
 *
 * @returns {Record<K, T[]>} A plain object whose keys are the distinct values
 *   returned by `keyFn` and whose values are arrays of items that produced
 *   that key, **in their original order**.
 *
 * @throws {TypeError} If `arr` is not an array.
 * @throws {TypeError} If `keyFn` is not a function.
 *
 * @example
 * // Group numbers by even / odd
 * groupBy([1, 2, 3, 4, 5], n => (n % 2 === 0 ? 'even' : 'odd'));
 * // → { odd: [1, 3, 5], even: [2, 4] }
 *
 * @example
 * // Group objects by a property
 * const people = [
 *   { name: 'Alice', dept: 'Engineering' },
 *   { name: 'Bob',   dept: 'Marketing'   },
 *   { name: 'Carol', dept: 'Engineering' },
 * ];
 * groupBy(people, p => p.dept);
 * // → {
 * //     Engineering: [{ name: 'Alice', … }, { name: 'Carol', … }],
 * //     Marketing:   [{ name: 'Bob', … }],
 * //   }
 *
 * @example
 * // Use the index as part of the key
 * groupBy(['a', 'b', 'c', 'd'], (_, i) => (i < 2 ? 'first-half' : 'second-half'));
 * // → { 'first-half': ['a', 'b'], 'second-half': ['c', 'd'] }
 */
function groupBy(arr, keyFn) {
  // ── Guard clauses ──────────────────────────────────────────────────────────
  if (!Array.isArray(arr)) {
    throw new TypeError(
      `groupBy: expected first argument to be an Array, got ${typeof arr}`
    );
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(
      `groupBy: expected second argument to be a function, got ${typeof keyFn}`
    );
  }

  // ── Core logic ─────────────────────────────────────────────────────────────
  return arr.reduce((groups, item, index, array) => {
    const key = keyFn(item, index, array);

    // Initialise the bucket on first encounter, then push.
    if (!Object.prototype.hasOwnProperty.call(groups, key)) {
      groups[key] = [];
    }
    groups[key].push(item);

    return groups;
  }, Object.create(null)); // null-prototype avoids collisions with built-in keys
