## Key Design Decisions

| Decision | Rationale |
|---|---|
| **`Object.create(null)`** | Returns a null-prototype object, preventing accidental collisions with inherited keys like `toString`, `constructor`, or `hasOwnProperty`. |
| **`hasOwnProperty` guard** | Safely checks bucket existence even when the key matches a prototype property name. |
| **Passes `(item, index, array)` to `keyFn`** | Mirrors the `Array.prototype.map` / `forEach` contract — familiar and occasionally useful (e.g., grouping by position). |
| **Strict input validation** | Fails fast with a descriptive `TypeError` rather than silently producing wrong results. |
| **Original order preserved** | Items are pushed in iteration order, so each bucket's array is a stable sub-sequence of the input. |

# `groupBy` Utility Function

## Implementation

```javascript
/**
 * Groups an array of items into an object (or Map) where each key corresponds
 * to a group of items that share the same derived key value.
 *
 * @template T        - The type of elements in the input array.
 * @template K        - The type of the derived key (string | number | symbol).
 *
 * @param {T[]} arr
 *   The array of items to group. Passing an empty array returns an empty object.
 *   `null` / `undefined` values inside the array are forwarded to `keyFn` as-is.
 *
 * @param {(item: T, index: number, array: T[]) => K} keyFn
 *   A function called for every element that returns the key under which that
 *   element should be grouped.
 *   - Receives the same three arguments as `Array.prototype.map` callbacks:
 *     `item`, `index`, and the original `array`.
 *   - Must return a value that is a valid object key (string, number, or symbol).
 *   - Throwing inside `keyFn` will propagate the error to the caller.
 *
 * @returns {Record<K, T[]>}
 *   A plain object whose keys are the distinct values returned by `keyFn` and
 *   whose values are arrays of items (in their original order) that produced
 *   that key.
 *
 * @throws {TypeError} If `arr` is not an array.
 * @throws {TypeError} If `keyFn` is not a function.
 *
 * @example
 * // ── Group by a primitive property ──────────────────────────────────────
 * const people = [
 *   { name: 'Alice', department: 'Engineering' },
 *   { name: 'Bob',   department: 'Marketing'   },
 *   { name: 'Carol', department: 'Engineering' },
 *   { name: 'Dave',  department: 'Marketing'   },
 * ];
 *
 * groupBy(people, (p) => p.department);
 * // {
 * //   Engineering: [{ name: 'Alice', … }, { name: 'Carol', … }],
 * //   Marketing:   [{ name: 'Bob',   … }, { name: 'Dave',  … }],
 * // }
 *
 * @example
 * // ── Group numbers by even / odd ─────────────────────────────────────────
 * groupBy([1, 2, 3, 4, 5], (n) => (n % 2 === 0 ? 'even' : 'odd'));
 * // { odd: [1, 3, 5], even: [2, 4] }
 *
 * @example
 * // ── Use the index as part of the key ────────────────────────────────────
 * groupBy(['a', 'b', 'c', 'd'], (_, i) => (i < 2 ? 'first-half' : 'second-half'));
 * // { 'first-half': ['a', 'b'], 'second-half': ['c', 'd'] }
 *
 * @example
 * // ── Group by computed / transformed value ───────────────────────────────
 * const words = ['one', 'two', 'three', 'four', 'five'];
 * groupBy(words, (w) => w.length);
 * // { 3: ['one', 'two'], 5: ['three', 'four', 'five'] }  ← wait, 'four' has 4
 * // Corrected:
 * // { 3: ['one', 'two'], 5: ['three'], 4: ['four', 'five'] }
 */
function groupBy(arr, keyFn) {
  // ── Guard clauses ──────────────────────────────────────────────────────────
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupBy: expected an array as the first argument, got ${typeof arr}`);
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(`groupBy: expected a function as the second argument, got ${typeof keyFn}`);
  }

  // ── Core reduction ─────────────────────────────────────────────────────────
  return arr.reduce((groups, item, index) => {
    // Derive the key for this item; let errors bubble up naturally.
    const key = keyFn(item, index, arr);

    // Initialise the bucket on first encounter, then push.
    if (!Object.prototype.hasOwnProperty.call(groups, key)) {
      groups[key] = [];
    }
    groups[key].push(item);

    return groups;
  }, Object.create(null)); // null-prototype avoids collisions with built-in keys
}
```

