## Design Decisions

| Decision | Rationale |
|---|---|
| **`Object.create(null)`** | Returns a null-prototype object, eliminating collisions with inherited keys like `toString`, `constructor`, or `hasOwnProperty`. |
| **`hasOwnProperty` via `Object.prototype`** | Avoids breakage if the result object's own `hasOwnProperty` is shadowed (e.g., when the key is literally `"hasOwnProperty"`). |
| **Same callback signature as `Array#map`** | Consistent with native APIs — `(item, index, array)` — so existing callbacks are reusable. |
| **Errors bubble from `keyFn`** | Swallowing errors would hide bugs; callers should handle them explicitly. |
| **Preserves insertion order** | Items within each group appear in the same order as in the source array, matching user expectations. |

# `groupBy` Utility Function

## Implementation

```javascript
/**
 * Groups an array of items into an object (or Map) where each key corresponds
 * to a group of items that share the same derived key value.
 *
 * @template T - The type of items in the input array.
 * @template K - The type of the derived key (must be a valid object key: string | number | symbol).
 *
 * @param {T[]} arr - The array of items to group. Passing a non-array throws a TypeError.
 * @param {(item: T, index: number, array: T[]) => K} keyFn
 *   A function called for each item that returns the key under which the item
 *   should be grouped. Receives the same arguments as `Array.prototype.map`.
 *
 * @returns {Record<K, T[]>}
 *   A plain object whose keys are the distinct values returned by `keyFn` and
 *   whose values are arrays of items that produced that key, **in the order
 *   they appeared in the original array**.
 *
 * @throws {TypeError} If `arr` is not an array.
 * @throws {TypeError} If `keyFn` is not a function.
 *
 * @example
 * // ── Basic grouping by a property ──────────────────────────────────────────
 * const people = [
 *   { name: 'Alice', dept: 'Engineering' },
 *   { name: 'Bob',   dept: 'Marketing'   },
 *   { name: 'Carol', dept: 'Engineering' },
 * ];
 *
 * groupBy(people, p => p.dept);
 * // {
 * //   Engineering: [{ name: 'Alice', … }, { name: 'Carol', … }],
 * //   Marketing:   [{ name: 'Bob',   … }],
 * // }
 *
 * @example
 * // ── Grouping numbers by a computed property ────────────────────────────────
 * groupBy([1, 2, 3, 4, 5, 6], n => (n % 2 === 0 ? 'even' : 'odd'));
 * // { odd: [1, 3, 5], even: [2, 4, 6] }
 *
 * @example
 * // ── Grouping by index bucket (every 3 items) ───────────────────────────────
 * groupBy(['a', 'b', 'c', 'd', 'e'], (_, i) => Math.floor(i / 3));
 * // { 0: ['a', 'b', 'c'], 1: ['d', 'e'] }
 *
 * @example
 * // ── Empty array returns an empty object ────────────────────────────────────
 * groupBy([], x => x.type); // {}
 */
function groupBy(arr, keyFn) {
  // ── Guard clauses ──────────────────────────────────────────────────────────
  if (!Array.isArray(arr)) {
    throw new TypeError(
      `groupBy: expected first argument to be an Array, got ${typeof arr}`
    );
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(
      `groupBy: expected second argument to be a function, got ${typeof keyFn}`
    );
  }

  // ── Core reduction ─────────────────────────────────────────────────────────
  return arr.reduce((groups, item, index) => {
    const key = keyFn(item, index, arr);

    // Initialise the bucket on first encounter, then push.
    if (!Object.prototype.hasOwnProperty.call(groups, key)) {
      groups[key] = [];
    }
    groups[key].push(item);

    return groups;
  }, Object.create(null)); // null-prototype avoids collisions with built-in keys
}
