## Implementation

```javascript
/**
 * Groups an array of items into an object (map) where each key is derived
 * from a user-supplied key function, and each value is an array of items
 * that produced that key.
 *
 * @template T        - The type of elements in the input array.
 * @template K        - The type of the derived key (must be a valid object key:
 *                      string | number | symbol).
 *
 * @param {T[]} arr   - The array of items to group. An empty array returns {}.
 *                      Passing null / undefined throws a TypeError.
 * @param {function(item: T, index: number, array: T[]): K} keyFn
 *                    - A pure function called once per element that returns the
 *                      grouping key for that element.
 *                      • Receives the same three arguments as Array#map callbacks.
 *                      • Returning undefined is allowed; those items are grouped
 *                        under the key "undefined".
 *                      • Throwing inside keyFn propagates the error to the caller.
 *
 * @returns {Object.<K, T[]>}
 *          A plain object whose own enumerable properties are the distinct keys
 *          returned by keyFn, each mapped to a non-empty array of matching items
 *          in their original order.
 *
 * @throws {TypeError} If `arr` is not an array.
 * @throws {TypeError} If `keyFn` is not a function.
 *
 * @example
 * // ── Group numbers by even / odd ──────────────────────────────────────────
 * groupBy([1, 2, 3, 4, 5], n => (n % 2 === 0 ? 'even' : 'odd'));
 * // → { odd: [1, 3, 5], even: [2, 4] }
 *
 * @example
 * // ── Group objects by a property ──────────────────────────────────────────
 * const people = [
 *   { name: 'Alice', dept: 'Engineering' },
 *   { name: 'Bob',   dept: 'Design'      },
 *   { name: 'Carol', dept: 'Engineering' },
 * ];
 * groupBy(people, p => p.dept);
 * // → {
 * //     Engineering: [{ name: 'Alice', … }, { name: 'Carol', … }],
 * //     Design:      [{ name: 'Bob',   … }],
 * //   }
 *
 * @example
 * // ── Group strings by first character ─────────────────────────────────────
 * groupBy(['apple', 'avocado', 'banana', 'blueberry'], s => s[0]);
 * // → { a: ['apple', 'avocado'], b: ['banana', 'blueberry'] }
 *
 * @example
 * // ── Use the index argument ────────────────────────────────────────────────
 * groupBy(['a', 'b', 'c', 'd'], (_, i) => (i < 2 ? 'first-half' : 'second-half'));
 * // → { 'first-half': ['a', 'b'], 'second-half': ['c', 'd'] }
 */
function groupBy(arr, keyFn) {
  // ── Guard clauses ──────────────────────────────────────────────────────────
  if (!Array.isArray(arr)) {
    throw new TypeError(
      `groupBy: expected an array as the first argument, got ${typeof arr}`
    );
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(
      `groupBy: expected a function as the second argument, got ${typeof keyFn}`
    );
  }

  // ── Core reduction ────────────────────────────────────────────────────────
  // Object.create(null) avoids prototype pollution (no inherited keys like
  // "constructor", "toString", etc. can clash with user-derived keys).
  return arr.reduce((groups, item, index, array) => {
    const key = keyFn(item, index, array);

    // Initialise the bucket on first encounter, then push.
    if (!Object.prototype.hasOwnProperty.call(groups, key)) {
      groups[key] = [];
    }
    groups[key].push(item);

    return groups;
  }, Object.create(null));
}
