 * @param {(item: T) => K} keyFn - A function that receives each item and
 *                                 returns the key it should be grouped under.
 *                                 - Returning `null` or `undefined` places the
 *                                   item under the key `"null"` / `"undefined"`.
 *                                 - The function is called once per element, in
 *                                   order, with no mutation of the original array.
 *
 * @returns {Record<K, T[]>} A plain object whose keys are the distinct values
 *                           returned by `keyFn` and whose values are arrays of
 *                           items that produced that key, preserving insertion
 *                           order within each group.
 *
 * @throws {TypeError} If `arr` is not an array.
 * @throws {TypeError} If `keyFn` is not a function.
 *
 * @example
 * // ── Group by a primitive property ──────────────────────────────────────
 * const people = [
 *   { name: 'Alice', dept: 'Engineering' },
 *   { name: 'Bob',   dept: 'Marketing'   },
 *   { name: 'Carol', dept: 'Engineering' },
 * ];
 *
 * groupBy(people, p => p.dept);
 * // {
 * //   Engineering: [{ name: 'Alice', … }, { name: 'Carol', … }],
 * //   Marketing:   [{ name: 'Bob',   … }],
 * // }
 *
 * @example
 * // ── Group numbers by even / odd ─────────────────────────────────────────
 * groupBy([1, 2, 3, 4, 5], n => (n % 2 === 0 ? 'even' : 'odd'));
 * // { odd: [1, 3, 5], even: [2, 4] }
 *
 * @example
 * // ── Group by computed / transformed key ─────────────────────────────────
 * const words = ['apple', 'ant', 'banana', 'avocado', 'blueberry'];
 * groupBy(words, w => w[0]);          // group by first letter
 * // { a: ['apple', 'ant', 'avocado'], b: ['banana', 'blueberry'] }
 *
 * @example
 * // ── Empty array ──────────────────────────────────────────────────────────
 * groupBy([], x => x.type);           // {}
 */
function groupBy(arr, keyFn) {
  // ── Guard clauses ──────────────────────────────────────────────────────────
  if (!Array.isArray(arr)) {
    throw new TypeError(
      `groupBy: expected first argument to be an Array, got ${typeof arr}`
    );
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(
      `groupBy: expected second argument to be a Function, got ${typeof keyFn}`
    );
  }

  // ── Core logic ─────────────────────────────────────────────────────────────
  return arr.reduce((groups, item) => {
    const key = keyFn(item);

    // Initialise the bucket on first encounter; then push.
    if (!Object.prototype.hasOwnProperty.call(groups, key)) {
      groups[key] = [];
    }
    groups[key].push(item);

    return groups;
  }, Object.create(null)); // null-prototype avoids key collisions with built-ins
