/**
 * Groups an array of items into an object (or Map) where each key corresponds
 * to a group of items that share the same derived key value.
 *
 * @template T - The type of items in the input array.
 * @template K - The type of the derived key (must be a valid object key: string | number | symbol).
 *
 * @param {T[]} arr - The array of items to group. Must be a non-null array.
 * @param {(item: T, index: number, array: T[]) => K} keyFn
 *   A function called for each element that returns the key under which
 *   that element should be grouped. Receives the current item, its index,
 *   and the original array — matching the signature of Array.prototype.map.
 *
 * @returns {Record<K, T[]>}
 *   A plain object whose keys are the distinct values returned by `keyFn`
 *   and whose values are arrays of items that produced that key, preserving
 *   their original relative order.
 *
 * @throws {TypeError} If `arr` is not an array.
 * @throws {TypeError} If `keyFn` is not a function.
 *
 * @example
 * // --- Group numbers by even / odd ---
 * groupBy([1, 2, 3, 4, 5], n => (n % 2 === 0 ? 'even' : 'odd'));
 * // => { odd: [1, 3, 5], even: [2, 4] }
 *
 * @example
 * // --- Group objects by a property ---
 * const people = [
 *   { name: 'Alice', dept: 'Engineering' },
 *   { name: 'Bob',   dept: 'Marketing'   },
 *   { name: 'Carol', dept: 'Engineering' },
 * ];
 * groupBy(people, p => p.dept);
 * // => {
 * //   Engineering: [{ name: 'Alice', … }, { name: 'Carol', … }],
 * //   Marketing:   [{ name: 'Bob',   … }],
 * // }
 *
 * @example
 * // --- Group by computed / transformed value ---
 * const words = ['apple', 'ant', 'banana', 'avocado', 'blueberry'];
 * groupBy(words, w => w[0]);
 * // => { a: ['apple', 'ant', 'avocado'], b: ['banana', 'blueberry'] }
 *
 * @example
 * // --- Gracefully handles an empty array ---
 * groupBy([], x => x);
 * // => {}
 */
function groupBy(arr, keyFn) {
  // ── Guard clauses ────────────────────────────────────────────────────────────
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupBy: first argument must be an array, got ${typeof arr}`);
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(`groupBy: second argument must be a function, got ${typeof keyFn}`);
  }

  // ── Core logic ───────────────────────────────────────────────────────────────
  return arr.reduce((groups, item, index) => {
    const key = keyFn(item, index, arr);

    // Initialise the bucket the first time a key is encountered.
    if (!Object.prototype.hasOwnProperty.call(groups, key)) {
      groups[key] = [];
    }

    groups[key].push(item);
    return groups;
  }, Object.create(null)); // null-prototype avoids collisions with inherited keys
                           // (e.g. a key named "constructor" or "toString")
