## Key Design Decisions

| Decision | Rationale |
|---|---|
| **`Object.create(null)`** | Avoids prototype pollution — keys like `"constructor"` or `"hasOwnProperty"` won't collide with inherited properties |
| **`Object.prototype.hasOwnProperty.call`** | Safe existence check that works even on null-prototype objects |
| **`keyFn(item, index, array)`** | Mirrors the `Array.prototype.map` callback signature — familiar and more powerful than `(item) => key` alone |
| **Guard clauses with `TypeError`** | Fail fast with descriptive messages rather than producing silent, hard-to-debug output |
| **Preserves insertion order** | Items within each group appear in the same relative order as they did in the original array |

# `groupBy` Utility Function

## Implementation

```javascript
/**
 * Groups an array of items into an object (map) where each key is derived
 * from the provided `keyFn` function, and each value is an array of items
 * that produced that key.
 *
 * @template T        - The type of items in the input array.
 * @template K        - The type of the derived key (string | number | symbol).
 *
 * @param {T[]} arr           - The array of items to group.
 * @param {(item: T) => K} keyFn
 *   A function called once per item that returns the key the item should
 *   be grouped under.  The return value is coerced to a string when used
 *   as an object property, so prefer string | number | symbol for
 *   predictable results.
 *
 * @returns {Record<K, T[]>}
 *   A plain object whose own enumerable properties are the distinct keys
 *   returned by `keyFn`, each mapped to a non-empty array of items that
 *   produced that key.  Items appear in the same relative order as they
 *   did in `arr`.
 *
 * @throws {TypeError} If `arr` is not an array.
 * @throws {TypeError} If `keyFn` is not a function.
 *
 * @example
 * // ── Group primitives ────────────────────────────────────────────────
 * groupBy([1, 2, 3, 4, 5], n => (n % 2 === 0 ? 'even' : 'odd'));
 * // { odd: [1, 3, 5], even: [2, 4] }
 *
 * @example
 * // ── Group objects by a property ──────────────────────────────────────
 * const people = [
 *   { name: 'Alice', dept: 'Engineering' },
 *   { name: 'Bob',   dept: 'Marketing'   },
 *   { name: 'Carol', dept: 'Engineering' },
 * ];
 * groupBy(people, p => p.dept);
 * // {
 * //   Engineering: [{ name: 'Alice', … }, { name: 'Carol', … }],
 * //   Marketing:   [{ name: 'Bob',   … }],
 * // }
 *
 * @example
 * // ── Group by computed / transformed key ──────────────────────────────
 * const words = ['apple', 'banana', 'avocado', 'blueberry', 'cherry'];
 * groupBy(words, w => w[0].toUpperCase());
 * // { A: ['apple', 'avocado'], B: ['banana', 'blueberry'], C: ['cherry'] }
 *
 * @example
 * // ── Empty array returns empty object ─────────────────────────────────
 * groupBy([], x => x);
 * // {}
 */
function groupBy(arr, keyFn) {
  // ── Guard clauses ────────────────────────────────────────────────────────
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupBy: expected an array as the first argument, got ${typeof arr}`);
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(`groupBy: expected a function as the second argument, got ${typeof keyFn}`);
  }

  // ── Core reduction ───────────────────────────────────────────────────────
  return arr.reduce((groups, item, index) => {
    // Derive the key for this item.
    const key = keyFn(item, index, arr); // index & arr mirror Array#map signature

    // Initialise the bucket on first encounter, then push.
    if (!Object.prototype.hasOwnProperty.call(groups, key)) {
      groups[key] = [];
    }
    groups[key].push(item);

    return groups;
  }, Object.create(null)); // null prototype avoids key collisions with built-ins
}
