const sameKey = groupBy([1, 2, 3], () => 'all');
assert(deepEqual(sameKey['all'], [1, 2, 3]), 'all items under one key');

// 6. Each item gets its own key
const uniqueKeys = groupBy(['x', 'y', 'z'], s => s);
assert(uniqueKeys['x'].length === 1, 'unique key x');
assert(uniqueKeys['y'].length === 1, 'unique key y');
assert(uniqueKeys['z'].length === 1, 'unique key z');

// 7. Dangerous prototype key names don't cause collisions
const dangerous = [
  { key: 'constructor' },
  { key: 'toString'    },
  { key: '__proto__'   },
];
const byDangerousKey = groupBy(dangerous, o => o.key);
assert(Array.isArray(byDangerousKey['constructor']), 'handles "constructor" key safely');
assert(Array.isArray(byDangerousKey['toString']),    'handles "toString" key safely');

// 8. TypeError on bad first argument
try {
  groupBy('not-an-array', x => x);
  assert(false, 'should have thrown for non-array');
} catch (e) {
  assert(e instanceof TypeError, 'throws TypeError for non-array input');
}

// 9. TypeError on bad second argument
try {
  groupBy([1, 2], 'not-a-function');
  assert(false, 'should have thrown for non-function keyFn');
} catch (e) {
  assert(e instanceof TypeError, 'throws TypeError for non-function keyFn');
}

// 10. Preserves item references (no cloning)
const obj = { id: 1 };
const result = groupBy([obj], o => o.id);
assert(result[1][0] === obj, 'items are the same references, not copies');
