## Bonus: `groupByMap` — preserves exact key types

```javascript
/**
 * Identical semantics to {@link groupBy} but returns a `Map` instead of a
 * plain object, which means:
 *
 * - Keys are **not** coerced to strings — objects, symbols, and `undefined`
 *   are stored as-is.
 * - Iteration order follows insertion order (same as `Map`).
 * - Slightly slower lookup than a plain object for string keys.
 *
 * @template T
 * @template K
 * @param {T[]} arr
 * @param {(item: T, index: number, array: T[]) => K} keyFn
 * @returns {Map<K, T[]>}
 *
 * @example
 * // Symbol keys — impossible with a plain object
 * const ODD  = Symbol('odd');
 * const EVEN = Symbol('even');
 *
 * groupByMap([1, 2, 3, 4], n => (n % 2 === 0 ? EVEN : ODD));
 * // Map { Symbol(odd) => [1, 3], Symbol(even) => [2, 4] }
 */
function groupByMap(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupByMap: first argument must be an array, got ${typeof arr}`);
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(`groupByMap: second argument must be a function, got ${typeof keyFn}`);
  }

  return arr.reduce((map, item, index) => {
    const key = keyFn(item, index, arr);
    const bucket = map.get(key);

    if (bucket) {
      bucket.push(item);
    } else {
      map.set(key, [item]);
    }

    return map;
  }, new Map());
}
```

