## Key Design Decisions

| Decision | Rationale |
|---|---|
| **`Object.create(null)`** as accumulator | Returns an object with no inherited properties, so keys like `toString` or `valueOf` work correctly as group keys |
| **`hasOwnProperty` check** before push | Avoids accidentally reading an inherited property when deciding whether to create a new bucket |
| **Prototype-pollution guard** | Keys `__proto__`, `constructor`, and `prototype` are blocked because they can corrupt the object in older runtimes |
| **`keyFn(item, index, array)`** signature | Mirrors `Array.prototype.map` / `forEach` — familiar and gives callers access to position context |
| **TypeError on bad inputs** | Fails loudly and early with a descriptive message rather than returning silently wrong results |

# `groupBy` Utility Function

## Implementation

```javascript
/**
 * Groups an array of items into an object where each key maps to an array
 * of items that share that key, as determined by a key-derivation function.
 *
 * @template T - The type of items in the input array.
 * @template K - The type of the derived key (must be a valid object key: string | number | symbol).
 *
 * @param {T[]} arr - The array of items to group.
 * @param {(item: T, index: number, array: T[]) => K} keyFn - A function that
 *   derives a grouping key from each item. Receives the current item, its
 *   index, and the original array (mirroring the signature of Array.prototype.map).
 *
 * @returns {Record<K, T[]>} An object whose keys are the distinct values
 *   returned by `keyFn`, and whose values are arrays of items that produced
 *   that key — in the order they appeared in the original array.
 *
 * @throws {TypeError} If `arr` is not an array.
 * @throws {TypeError} If `keyFn` is not a function.
 *
 * @example
 * // Group numbers by even / odd
 * groupBy([1, 2, 3, 4, 5], n => (n % 2 === 0 ? 'even' : 'odd'));
 * // → { odd: [1, 3, 5], even: [2, 4] }
 *
 * @example
 * // Group people by age bracket
 * const people = [
 *   { name: 'Alice', age: 25 },
 *   { name: 'Bob',   age: 17 },
 *   { name: 'Carol', age: 32 },
 *   { name: 'Dave',  age: 15 },
 * ];
 * groupBy(people, p => (p.age >= 18 ? 'adult' : 'minor'));
 * // → {
 * //     adult: [{ name: 'Alice', age: 25 }, { name: 'Carol', age: 32 }],
 * //     minor: [{ name: 'Bob',   age: 17 }, { name: 'Dave',  age: 15 }],
 * //   }
 *
 * @example
 * // Group words by first letter
 * groupBy(['apple', 'avocado', 'banana', 'blueberry', 'cherry'], w => w[0]);
 * // → { a: ['apple', 'avocado'], b: ['banana', 'blueberry'], c: ['cherry'] }
 *
 * @example
 * // Use the index as part of the key (e.g., chunk into pairs)
 * groupBy(['a', 'b', 'c', 'd', 'e'], (_, i) => Math.floor(i / 2));
 * // → { 0: ['a', 'b'], 1: ['c', 'd'], 2: ['e'] }
 */
function groupBy(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupBy: expected an array, got ${typeof arr}`);
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(`groupBy: expected a function, got ${typeof keyFn}`);
  }

  return arr.reduce((groups, item, index) => {
    const key = keyFn(item, index, arr);

    // Initialise the bucket on first encounter, then push.
    if (!Object.prototype.hasOwnProperty.call(groups, key)) {
      groups[key] = [];
    }
    groups[key].push(item);

    return groups;
  }, Object.create(null)); // null prototype avoids key collisions with Object built-ins
}
```

