## Key Design Decisions

| Decision | Rationale |
|---|---|
| **`Object.create(null)`** as accumulator | Avoids accidental collisions with inherited properties like `constructor`, `toString`, `__proto__` |
| **`hasOwnProperty` via `Object.prototype.call`** | Safe even when the result object has no prototype |
| **Mirror `Array.map` callback signature** `(item, index, array)` | Consistent with native array methods; lets callers use the index as a grouping dimension |
| **Generic types `T` / `K`** | Works with any item type and any key type (`string`, `number`, `symbol`) |
| **Eager `TypeError`** | Fails fast with a clear message instead of producing a silent wrong result |

# `groupBy` Utility Function

## Implementation

```javascript
/**
 * Groups an array of items into an object where each key maps to an array
 * of items that share the same derived key value.
 *
 * @template T - The type of items in the input array.
 * @template K - The type of the derived key (must be a valid object key: string | number | symbol).
 *
 * @param {T[]} arr - The array of items to group. Returns an empty object for empty arrays.
 * @param {function(item: T, index: number, array: T[]): K} keyFn - A function that derives
 *   a grouping key from each item. Receives the current item, its index, and the full array
 *   (matching the signature of Array.prototype.map).
 *
 * @returns {Record<K, T[]>} An object where each key is a derived group key and each value
 *   is an array of items belonging to that group, preserving their original order.
 *
 * @throws {TypeError} If `arr` is not an array.
 * @throws {TypeError} If `keyFn` is not a function.
 *
 * @example
 * // Group numbers by even/odd
 * groupBy([1, 2, 3, 4, 5], n => n % 2 === 0 ? 'even' : 'odd');
 * // → { odd: [1, 3, 5], even: [2, 4] }
 *
 * @example
 * // Group objects by a property
 * const people = [
 *   { name: 'Alice', department: 'Engineering' },
 *   { name: 'Bob',   department: 'Marketing' },
 *   { name: 'Carol', department: 'Engineering' },
 * ];
 * groupBy(people, person => person.department);
 * // → {
 * //     Engineering: [{ name: 'Alice', ... }, { name: 'Carol', ... }],
 * //     Marketing:   [{ name: 'Bob', ... }],
 * //   }
 *
 * @example
 * // Group strings by their first character
 * groupBy(['apple', 'avocado', 'banana', 'blueberry'], fruit => fruit[0]);
 * // → { a: ['apple', 'avocado'], b: ['banana', 'blueberry'] }
 *
 * @example
 * // Group with index-aware key function
 * groupBy(['a', 'b', 'c', 'd'], (_, index) => index % 2 === 0 ? 'even-index' : 'odd-index');
 * // → { 'even-index': ['a', 'c'], 'odd-index': ['b', 'd'] }
 */
function groupBy(arr, keyFn) {
  if (!Array.isArray(arr)) {
    throw new TypeError(`groupBy: expected an array, got ${typeof arr}`);
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(`groupBy: expected a function as second argument, got ${typeof keyFn}`);
  }

  return arr.reduce((groups, item, index) => {
    const key = keyFn(item, index, arr);

    // Guard against keys that would corrupt the object (e.g. '__proto__')
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
      throw new TypeError(`groupBy: derived key "${String(key)}" is not allowed`);
    }

    if (Object.prototype.hasOwnProperty.call(groups, key)) {
      groups[key].push(item);
    } else {
      groups[key] = [item];
    }

    return groups;
  }, Object.create(null)); // null prototype avoids inherited property collisions
}
