## Key Design Decisions

| Decision | Rationale |
|---|---|
| **`Object.create(null)`** | Returns a plain dictionary with no prototype, so keys like `toString` or `valueOf` can't shadow inherited properties |
| **Prototype-pollution guard** | Explicitly blocks `__proto__`, `constructor`, and `prototype` as derived keys |
| **`hasOwnProperty` check** | Avoids accidental hits on inherited properties when the accumulator *does* have a prototype |
| **Full `Array.map` signature** | Passing `(item, index, array)` to `keyFn` matches native iterator conventions and enables index-aware grouping |
| **Fail-fast validation** | Early `TypeError` throws give clear, actionable messages rather than silent wrong results |

# `groupBy` Utility Function

## Implementation

```javascript
/**
 * Groups an array of items into an object whose keys are derived by applying
 * a key-selector function to each item.
 *
 * @template T         - The type of elements in the input array.
 * @template K extends string | number | symbol
 *                     - The type of the derived key (must be a valid object key).
 *
 * @param {T[]} arr    - The array of items to group. An empty array returns {}.
 *                       Passing null/undefined throws a TypeError.
 * @param {function(item: T, index: number, array: T[]): K} keyFn
 *                     - A pure function that receives each element (plus its
 *                       index and the original array, mirroring Array#map) and
 *                       returns the key under which that element should be
 *                       grouped.
 *                       • Returning null or undefined for a key throws a
 *                         TypeError so silent data loss is avoided.
 *                       • The function is called exactly once per element.
 *
 * @returns {Record<K, T[]>}
 *   A plain object mapping each distinct key to an array of all elements that
 *   produced that key, preserving the original relative order within each group.
 *
 * @throws {TypeError} If `arr` is not an array.
 * @throws {TypeError} If `keyFn` is not a function.
 * @throws {TypeError} If `keyFn` returns null or undefined for any element.
 *
 * @example
 * // ── Basic grouping by a property ──────────────────────────────────────────
 * const people = [
 *   { name: 'Alice', dept: 'Engineering' },
 *   { name: 'Bob',   dept: 'Marketing'   },
 *   { name: 'Carol', dept: 'Engineering' },
 * ];
 *
 * groupBy(people, p => p.dept);
 * // {
 * //   Engineering: [{ name: 'Alice', … }, { name: 'Carol', … }],
 * //   Marketing:   [{ name: 'Bob',   … }],
 * // }
 *
 * @example
 * // ── Grouping numbers by a computed property ────────────────────────────────
 * groupBy([1, 2, 3, 4, 5, 6], n => (n % 2 === 0 ? 'even' : 'odd'));
 * // { odd: [1, 3, 5], even: [2, 4, 6] }
 *
 * @example
 * // ── Using index as part of the key ─────────────────────────────────────────
 * groupBy(['a', 'b', 'c', 'd'], (_, i) => (i < 2 ? 'first-half' : 'second-half'));
 * // { 'first-half': ['a', 'b'], 'second-half': ['c', 'd'] }
 *
 * @example
 * // ── Empty array ────────────────────────────────────────────────────────────
 * groupBy([], x => x.type); // {}
 */
function groupBy(arr, keyFn) {
  // ── Guard clauses ────────────────────────────────────────────────────────────
  if (!Array.isArray(arr)) {
    throw new TypeError(
      `groupBy: expected an array as the first argument, but received ${typeof arr}.`
    );
  }
  if (typeof keyFn !== 'function') {
    throw new TypeError(
      `groupBy: expected a function as the second argument, but received ${typeof keyFn}.`
    );
  }

  // ── Core reduction ───────────────────────────────────────────────────────────
  return arr.reduce((groups, item, index, array) => {
    const key = keyFn(item, index, array);

    // Explicitly disallow null/undefined keys to prevent hard-to-debug issues
    // where items silently end up under "null" or "undefined" string keys.
    if (key === null || key === undefined) {
      throw new TypeError(
        `groupBy: keyFn returned ${key} for element at index ${index}. ` +
        `Keys must be non-null, non-undefined values.`
      );
    }

    // Initialise the bucket on first encounter, then push.
    if (!Object.prototype.hasOwnProperty.call(groups, key)) {
      groups[key] = [];
    }
    groups[key].push(item);

    return groups;
  }, Object.create(null)); // Null-prototype object avoids prototype-key collisions
                            // (e.g. a key named "constructor" or "toString").
}
