  assert(result.end.join()   === 'c,d', 'end group');
  console.log('✓ Index-based grouping');
}

// ── 5. Null-prototype — no prototype-key collisions ──────────────────────────
{
  const result = groupBy(
    [{ k: 'constructor' }, { k: 'toString' }, { k: 'constructor' }],
    x => x.k
  );
  assert(result['constructor'].length === 2, 'constructor key works safely');
  assert(result['toString'].length    === 1, 'toString key works safely');
  console.log('✓ Prototype-collision-safe keys');
}

// ── 6. Guard — non-array first argument ──────────────────────────────────────
{
  assertThrows(() => groupBy('not-an-array', x => x), TypeError, 'string input');
  assertThrows(() => groupBy(null,           x => x), TypeError, 'null input');
  assertThrows(() => groupBy(42,             x => x), TypeError, 'number input');
  console.log('✓ Guard: non-array first argument');
}

// ── 7. Guard — non-function second argument ──────────────────────────────────
{
  assertThrows(() => groupBy([1, 2], 'dept'),    TypeError, 'string keyFn');
  assertThrows(() => groupBy([1, 2], undefined), TypeError, 'undefined keyFn');
  console.log('✓ Guard: non-function second argument');
}

// ── 8. Guard — null/undefined key returned by keyFn ─────────────────────────
{
  assertThrows(() => groupBy([1], () => null),      TypeError, 'null key');
  assertThrows(() => groupBy([1], () => undefined), TypeError, 'undefined key');
  console.log('✓ Guard: null/undefined key from keyFn');
}

// ── 9. Original array is not mutated ─────────────────────────────────────────
{
  const input = [1, 2, 3];
  const copy  = [...input];
  groupBy(input, n => n % 2);
  assert(input.every((v, i) => v === copy[i]), 'Input array unchanged');
  console.log('✓ Input array not mutated');
}

console.log('\nAll tests passed ✓');
