## Design Decisions Explained

| Decision | Rationale |
|---|---|
| **`Object.create(null)`** as accumulator | Prevents collisions with inherited prototype keys like `constructor`, `toString`, `hasOwnProperty`. |
| **`Object.prototype.hasOwnProperty.call`** | Safe property check that works even on null-prototype objects. |
| **Reject `null`/`undefined` keys** | Avoids the silent footgun of items landing under the string `"null"` or `"undefined"`. |
| **Mirror `Array#map` signature** `(item, index, array)` | Consistent with the rest of the JS standard library; index and array are rarely needed but available. |
| **Single `reduce` pass** | O(n) time, O(n) space — each element is visited exactly once. |
| **No external dependencies** | Zero-dependency pure function; trivially portable and tree-shakeable. |

## Cache Class

```javascript
/**
 * A simple in-memory cache with optional TTL (time-to-live) support.
 *
 * @example
 * const cache = new Cache({ ttl: 5000 }); // entries expire after 5 seconds
 *
 * cache.set('user:1', { name: 'Alice' });
 * cache.get('user:1'); // { name: 'Alice' }
 * cache.has('user:1'); // true
 * cache.delete('user:1');
 * cache.has('user:1'); // false
 */
class Cache {
  /**
   * @param {object}  [options]
   * @param {number}  [options.ttl]  Default time-to-live in milliseconds.
   *                                 Omit (or pass 0) for entries that never expire.
   */
  constructor({ ttl = 0 } = {}) {
    this._defaultTtl = ttl;
    /** @type {Map<string, { value: any, expiresAt: number|null }>} */
    this._store = new Map();
  }

  // ─── Private helpers ────────────────────────────────────────────────────────

  /**
   * Returns true when an entry exists AND has not yet expired.
   * Automatically removes stale entries.
   *
   * @param {string} key
   * @returns {boolean}
   */
  _isAlive(key) {
    const entry = this._store.get(key);
    if (!entry) return false;

    if (entry.expiresAt !== null && Date.now() > entry.expiresAt) {
      this._store.delete(key); // lazy eviction
      return false;
    }

    return true;
  }

  // ─── Public API ─────────────────────────────────────────────────────────────

  /**
   * Retrieves the value associated with `key`.
   * Returns `undefined` if the key does not exist or has expired.
   *
   * @param {string} key
   * @returns {any}
   *
   * @example
   * cache.set('color', 'blue');
   * cache.get('color'); // 'blue'
   * cache.get('missing'); // undefined
   */
  get(key) {
    return this._isAlive(key) ? this._store.get(key).value : undefined;
  }

  /**
   * Stores a value under `key`, with an optional per-entry TTL.
   * Overwrites any existing entry for the same key.
   *
   * @param {string} key
   * @param {any}    value
   * @param {object} [options]
   * @param {number} [options.ttl]  Entry-level TTL in milliseconds.
   *                                Overrides the instance default.
   *                                Pass `0` to make this entry never expire.
   * @returns {this}  Returns the cache instance for chaining.
   *
   * @example
   * cache.set('session', token, { ttl: 30_000 }); // expires in 30 s
   * cache.set('config', settings);                 // uses default TTL
   */
  set(key, value, { ttl = this._defaultTtl } = {}) {
    this._store.set(key, {
      value,
      expiresAt: ttl > 0 ? Date.now() + ttl : null,
    });
    return this;
  }

  /**
   * Returns `true` if `key` exists in the cache and has not expired.
   *
   * @param {string} key
   * @returns {boolean}
   *
   * @example
   * cache.set('x', 1);
   * cache.has('x'); // true
   * cache.has('y'); // false
   */
  has(key) {
    return this._isAlive(key);
  }

  /**
   * Removes the entry for `key` from the cache.
   * Returns `true` if the entry existed (and was not expired), `false` otherwise.
   *
   * @param {string} key
   * @returns {boolean}
   *
   * @example
   * cache.set('tmp', 42);
   * cache.delete('tmp'); // true
   * cache.delete('tmp'); // false (already removed)
   */
  delete(key) {
    if (!this._isAlive(key)) return false;
    this._store.delete(key);
    return true;
  }
}
