   * @param {string} key        - The cache key.
   * @param {*}      value      - The value to cache (any serialisable type).
   * @param {number} [ttl=0]   - Time-to-live in milliseconds. `0` = no expiry.
   * @returns {Cache} The cache instance (enables method chaining).
   *
   * @example
   * cache.set('theme', 'dark');                  // no expiry
   * cache.set('session', token, 30 * 60 * 1000); // expires in 30 minutes
   * cache.set('a', 1).set('b', 2);               // chained
   */
  set(key, value, ttl = 0) {
    this.#store.set(key, {
      value,
      expiresAt: ttl > 0 ? Date.now() + ttl : null,
    });

    return this;
  }

