   * Checks whether a non-expired entry exists for the given key.
   *
   * @param {string} key - The cache key to check.
   * @returns {boolean} `true` if the key exists and has not expired.
   *
   * @example
   * cache.set('lang', 'en');
   * cache.has('lang');    // true
   * cache.has('missing'); // false
   */
  has(key) {
    return this.get(key) !== undefined;
  }

