### Usage examples

```javascript
// --- No TTL (entries live forever) ---
const cache = new Cache();

cache.set('lang', 'en').set('theme', 'dark'); // chainable
cache.get('lang');   // 'en'
cache.has('theme');  // true
cache.delete('lang');
cache.has('lang');   // false

// --- Default TTL ---
const shortCache = new Cache({ ttl: 1000 }); // 1-second default

shortCache.set('ping', 'pong');
shortCache.get('ping'); // 'pong'

await new Promise(r => setTimeout(r, 1100));
shortCache.get('ping'); // undefined (expired)

// --- Per-entry TTL override ---
const mixed = new Cache({ ttl: 500 });

mixed.set('short', 'a');              // expires in 500 ms (default)
mixed.set('long', 'b', { ttl: 10000 }); // expires in 10 s (override)
```

