  constructor({ ttl, maxSize } = {}) {
    this._ttl = ttl;
    this._maxSize = maxSize;
    /** @type {Map<string, { value: any, expiresAt: number|null }>} */
    this._store = new Map();
  }

  // ---------------------------------------------------------------------------
  // Public API
  // ---------------------------------------------------------------------------

  /**
   * Retrieves the value associated with the given key.
   *
   * Returns `undefined` if the key does not exist or has expired.
   * Expired entries are automatically removed on access.
   *
   * @param  {string} key - The cache key to look up.
   * @returns {*}          The stored value, or `undefined` if not found / expired.
   *
   * @example
   * cache.set('color', 'blue');
   * cache.get('color'); // 'blue'
   * cache.get('missing'); // undefined
   */
  get(key) {
    const entry = this._store.get(key);

    if (!entry) return undefined;

    if (this._isExpired(entry)) {
      this._store.delete(key);
      return undefined;
    }

    return entry.value;
  }

  /**
   * Stores a value under the given key.
   *
   * If the cache has reached `maxSize`, the oldest entry is evicted first
   * (FIFO eviction). An optional per-entry `ttl` overrides the default TTL.
   *
   * @param  {string} key          - The cache key.
   * @param  {*}      value        - The value to store (any serialisable type).
   * @param  {object} [options={}] - Per-entry options.
   * @param  {number} [options.ttl] - Entry-specific TTL in milliseconds.
   *                                  Overrides the instance-level default.
   * @returns {Cache}               The Cache instance (for chaining).
   *
   * @example
   * cache.set('theme', 'dark');
   * cache.set('session', token, { ttl: 30_000 }); // expires in 30 s
   * cache.set('a', 1).set('b', 2);                // chaining
   */
  set(key, value, { ttl } = {}) {
    // Evict the oldest entry when the cache is full.
    if (this._maxSize && this._store.size >= this._maxSize && !this._store.has(key)) {
      const oldestKey = this._store.keys().next().value;
      this._store.delete(oldestKey);
    }

    const effectiveTtl = ttl ?? this._ttl;
    const expiresAt = effectiveTtl ? Date.now() + effectiveTtl : null;

    this._store.set(key, { value, expiresAt });
    return this;
  }

  /**
   * Checks whether a non-expired entry exists for the given key.
   *
   * Expired entries are automatically removed during this check.
   *
   * @param  {string}  key - The cache key to check.
   * @returns {boolean}     `true` if the key exists and has not expired.
   *
   * @example
   * cache.set('ready', true);
   * cache.has('ready');   // true
   * cache.has('missing'); // false
   */
  has(key) {
    return this.get(key) !== undefined;
  }

  /**
   * Removes the entry associated with the given key.
   *
   * Does nothing if the key does not exist.
   *
   * @param  {string}  key - The cache key to remove.
   * @returns {boolean}     `true` if an entry was removed, `false` otherwise.
   *
   * @example
   * cache.set('temp', 42);
   * cache.delete('temp');    // true
   * cache.delete('missing'); // false
   */
  delete(key) {
    return this._store.delete(key);
  }

  // ---------------------------------------------------------------------------
  // Private helpers
  // ---------------------------------------------------------------------------

  /**
   * @private
   * @param  {{ expiresAt: number|null }} entry
   * @returns {boolean}
   */
  _isExpired(entry) {
    return entry.expiresAt !== null && Date.now() > entry.expiresAt;
  }
}
