// --- Bounded cache (FIFO eviction) ---
const bounded = new Cache({ maxSize: 2 });
bounded.set('a', 1).set('b', 2);
bounded.set('c', 3); // evicts 'a'
bounded.has('a');    // false
bounded.has('c');    // true
