   * cache.set('session', token, 30 * 60 * 1000);  // expires in 30 min
   * cache.set('a', 1).set('b', 2);                // chaining
   */
  set(key, value, ttl) {
    const expiresAt = ttl > 0 ? Date.now() + ttl : null;
    this.#store.set(key, { value, expiresAt });
    return this;
  }

