 * cache.get('user:1'); // { name: 'Alice' }
 * cache.has('user:1'); // true
 * cache.delete('user:1');
 * cache.has('user:1'); // false
 */
class Cache {
  /**
   * Creates a new Cache instance.
   *
   * @param {object} [options={}]
   * @param {number} [options.ttl] - Default time-to-live in milliseconds.
   *   Entries expire after this duration. Omit for entries that never expire.
   */
  constructor({ ttl } = {}) {
    this._defaultTtl = ttl;
    this._store = new Map();
  }

  // ---------------------------------------------------------------------------
  // Public API
  // ---------------------------------------------------------------------------

  /**
   * Retrieves the value associated with `key`.
   *
   * If the entry has expired it is deleted before returning `undefined`,
   * so stale data is never surfaced to the caller.
   *
   * @param {*} key - The cache key.
   * @returns {*} The stored value, or `undefined` if the key is missing or
   *   has expired.
   *
   * @example
   * cache.set('lang', 'en');
   * cache.get('lang'); // 'en'
   * cache.get('missing'); // undefined
   */
  get(key) {
    const entry = this._store.get(key);

    if (!entry) {
      return undefined;
    }

    if (this._isExpired(entry)) {
      this._store.delete(key);
      return undefined;
    }

    return entry.value;
  }

  /**
   * Stores a value under `key`, optionally overriding the default TTL.
   *
   * Calling `set` on an existing key overwrites both its value and its
   * expiry time.
   *
   * @param {*} key - The cache key.
   * @param {*} value - The value to store.
   * @param {object} [options={}]
   * @param {number} [options.ttl] - Entry-specific TTL in milliseconds.
   *   Overrides the instance-level default. Pass `0` to store without expiry.
   * @returns {Cache} The current instance, enabling method chaining.
   *
   * @example
   * cache.set('theme', 'dark');                    // uses default TTL
   * cache.set('session', token, { ttl: 30_000 }); // expires in 30 s
   * cache.set('theme', 'dark').set('lang', 'en'); // chaining
   */
  set(key, value, { ttl } = {}) {
    const resolvedTtl = ttl === 0 ? undefined : (ttl ?? this._defaultTtl);

    this._store.set(key, {
      value,
      expiresAt: resolvedTtl ? Date.now() + resolvedTtl : null,
    });

    return this;
  }

  /**
   * Checks whether a non-expired entry exists for `key`.
   *
   * Like `get`, this method treats expired entries as absent and removes
   * them as a side-effect.
   *
   * @param {*} key - The cache key.
   * @returns {boolean} `true` if the key exists and has not expired.
   *
   * @example
   * cache.set('ready', true);
   * cache.has('ready');   // true
   * cache.has('missing'); // false
   */
  has(key) {
    const entry = this._store.get(key);

    if (!entry) {
      return false;
    }

    if (this._isExpired(entry)) {
      this._store.delete(key);
      return false;
    }

    return true;
  }

  /**
   * Removes the entry for `key` from the cache.
   *
   * Deleting a key that does not exist (or has already expired) is a no-op
   * and returns `false`.
   *
   * @param {*} key - The cache key.
   * @returns {boolean} `true` if an entry was removed, `false` otherwise.
   *
   * @example
   * cache.set('tmp', 42);
   * cache.delete('tmp');     // true
   * cache.delete('tmp');     // false (already gone)
   * cache.delete('missing'); // false
   */
  delete(key) {
    return this._store.delete(key);
  }

  // ---------------------------------------------------------------------------
  // Private helpers
  // ---------------------------------------------------------------------------

  /**
   * Returns `true` when an entry has a finite expiry that is in the past.
   *
   * @private
   * @param {{ expiresAt: number|null }} entry
   * @returns {boolean}
   */
  _isExpired(entry) {
    return entry.expiresAt !== null && Date.now() > entry.expiresAt;
  }
