class Cache {
  /**
   * @param {object}  [options]           - Configuration options.
   * @param {number}  [options.ttl]       - Default time-to-live in milliseconds.
   *                                        Omit (or pass 0) for entries that never expire.
   * @param {number}  [options.maxSize]   - Maximum number of entries allowed.
   *                                        When the limit is reached the oldest entry is evicted.
   *                                        Omit (or pass 0) for an unbounded cache.
   */
  constructor({ ttl = 0, maxSize = 0 } = {}) {
    this._ttl = ttl;
    this._maxSize = maxSize;

    /** @type {Map<string, { value: any, expiresAt: number|null }>} */
    this._store = new Map();
  }

  // ─── Public API ────────────────────────────────────────────────────────────

  /**
   * Retrieves the value associated with `key`.
   *
   * Returns `undefined` if the key does not exist or its entry has expired.
   * Expired entries are automatically removed when accessed.
   *
   * @param {string} key - The cache key.
   * @returns {any} The stored value, or `undefined` if missing / expired.
   *
   * @example
   * cache.set('color', 'blue');
   * cache.get('color'); // 'blue'
   * cache.get('missing'); // undefined
   */
  get(key) {
    const entry = this._store.get(key);

    if (!entry) return undefined;

    if (this._isExpired(entry)) {
      this._store.delete(key);
      return undefined;
    }

    return entry.value;
  }

  /**
   * Stores a value under `key`, replacing any existing entry for that key.
   *
   * @param {string} key            - The cache key.
   * @param {any}    value          - The value to store (any serialisable type).
   * @param {object} [options]      - Per-entry options that override the cache defaults.
   * @param {number} [options.ttl]  - Time-to-live in milliseconds for this entry only.
   *                                  Pass `0` to make this specific entry never expire.
   * @returns {this} The cache instance (enables method chaining).
   *
   * @example
   * cache.set('token', 'abc123', { ttl: 60_000 }); // expires in 60 s
   * cache.set('config', { debug: true });           // uses the default TTL
   * cache.set('a', 1).set('b', 2);                  // chaining
   */
  set(key, value, { ttl = this._ttl } = {}) {
    // Evict the oldest entry when the cache is full (and key is new).
    if (this._maxSize > 0 && !this._store.has(key) && this._store.size >= this._maxSize) {
      const oldestKey = this._store.keys().next().value;
      this._store.delete(oldestKey);
    }

    this._store.set(key, {
      value,
      expiresAt: ttl > 0 ? Date.now() + ttl : null,
    });

    return this;
  }

