   * @param {string} key - The cache key to remove.
   * @returns {boolean} `true` if an entry was found and removed, `false` if the key did not exist.
   *
   * @example
   * cache.set('y', 99);
   * cache.delete('y'); // true
   * cache.delete('y'); // false (already gone)
   */
  delete(key) {
    return this._store.delete(key);
  }

