   * @type {number}
   *
   * @example
   * cache.set('a', 1).set('b', 2);
   * cache.size; // 2
   */
  get size() {
    return this._store.size;
  }

  // ─── Private helpers ───────────────────────────────────────────────────────

  /**
   * @param {{ expiresAt: number|null }} entry
   * @returns {boolean}
   */
  _isExpired(entry) {
    return entry.expiresAt !== null && Date.now() > entry.expiresAt;
  }
