short.set('temp', 42);
short.get('temp'); // 42

await new Promise(r => setTimeout(r, 150));

short.get('temp'); // undefined  (expired)
short.has('temp'); // false

// ── Per-entry TTL override ───────────────────────────────────────────────────
const mixed = new Cache({ ttl: 1_000 });

mixed.set('short', 'gone soon', { ttl: 50 });
mixed.set('long',  'still here');            // uses the 1 000 ms default

// ── Bounded cache (LRU-style eviction) ───────────────────────────────────────
const bounded = new Cache({ maxSize: 2 });

bounded.set('a', 1);
bounded.set('b', 2);
bounded.set('c', 3); // 'a' is evicted (oldest)

bounded.has('a'); // false
bounded.has('b'); // true
bounded.has('c'); // true

// ── Method chaining ──────────────────────────────────────────────────────────
cache.set('x', 10).set('y', 20).set('z', 30);

// ── Clearing everything ──────────────────────────────────────────────────────
cache.clear();
cache.size; // 0
```

---

## API summary

| Method / Property | Returns | Description |
|---|---|---|
| `new Cache(options?)` | `Cache` | Creates a cache. Accepts `ttl` (ms) and `maxSize`. |
| `get(key)` | `any` | Returns the value or `undefined` if missing/expired. |
| `set(key, value, options?)` | `this` | Stores a value; accepts a per-entry `ttl` override. |
| `has(key)` | `boolean` | `true` if the key exists and has not expired. |
| `delete(key)` | `boolean` | Removes an entry; `true` if it existed. |
| `clear()` | `void` | Removes all entries. |
| `size` | `number` | Current number of stored entries. |

# `fetchWithRetry` — Fetch with Exponential Backoff Retry

## Overview

A robust wrapper around the native `fetch` API that automatically retries failed requests using exponential backoff with optional jitter, giving transient network issues time to resolve before giving up.

---

## Implementation

```javascript
/**
 * Fetches a resource with automatic retry logic using exponential backoff.
 *
 * Retry behavior:
 *  - Retries on network errors (e.g., DNS failure, connection refused).
 *  - Retries on configurable HTTP status codes (default: 429, 500, 502, 503, 504).
 *  - Does NOT retry on client errors (4xx) unless explicitly listed in `retryOn`.
 *  - Delay between retries: baseDelay * 2^attempt ± jitter (milliseconds).
 *
 * @param {string | URL | Request} url
 *   The resource URL or a pre-built Request object.
 *
 * @param {RequestInit} [options={}]
 *   Standard fetch options (method, headers, body, signal, etc.).
 *   If `options.signal` is provided, an AbortError will NOT be retried.
 *
 * @param {object} [retryConfig={}]
 *   Configuration for retry behavior.
 *
 * @param {number} [retryConfig.retries=3]
 *   Maximum number of retry attempts (not counting the initial request).
 *   Total attempts = retries + 1.
 *
 * @param {number} [retryConfig.baseDelay=300]
 *   Base delay in milliseconds before the first retry.
 *   Subsequent delays are doubled each attempt: 300 → 600 → 1200 → …
 *
 * @param {number} [retryConfig.maxDelay=10000]
 *   Upper cap on delay in milliseconds, preventing runaway wait times.
 *
 * @param {number} [retryConfig.jitter=100]
 *   Maximum random jitter in milliseconds added to each delay to avoid
 *   thundering-herd problems when many clients retry simultaneously.
 *
 * @param {number[]} [retryConfig.retryOn=[429, 500, 502, 503, 504]]
 *   HTTP status codes that should trigger a retry.
 *
 * @param {function(attempt: number, error: Error|null, response: Response|null): void} [retryConfig.onRetry]
 *   Optional callback invoked before each retry.
 *   Useful for logging, metrics, or custom side-effects.
 *   - `attempt`  — the retry attempt number (1-based).
 *   - `error`    — the caught Error, or null if the failure was an HTTP status code.
 *   - `response` — the Response object, or null if the failure was a network error.
 *
 * @returns {Promise<Response>}
 *   Resolves with the first successful Response.
 *   Rejects with the last encountered Error if all attempts are exhausted,
 *   or immediately if the request is aborted.
 *
 * @throws {TypeError}   If `url` is not a valid URL string or Request object.
 * @throws {AbortError}  If the request is cancelled via AbortController.
 * @throws {Error}       The last network or HTTP error after all retries fail.
 *
 * @example
 * // Basic usage — 3 retries with default settings
 * const response = await fetchWithRetry('https://api.example.com/data');
 * const data = await response.json();
 *
 * @example
 * // POST request with custom retry config and logging
 * const response = await fetchWithRetry(
 *   'https://api.example.com/submit',
 *   {
 *     method: 'POST',
 *     headers: { 'Content-Type': 'application/json' },
 *     body: JSON.stringify({ key: 'value' }),
 *   },
 *   {
 *     retries: 5,
 *     baseDelay: 500,
 *     maxDelay: 15000,
 *     retryOn: [429, 500, 503],
 *     onRetry: (attempt, error, response) => {
 *       console.warn(`Retry #${attempt}`, error?.message ?? `HTTP ${response?.status}`);
 *     },
 *   }
 * );
 *
 * @example
 * // With AbortController timeout (no retries after abort)
 * const controller = new AbortController();
 * setTimeout(() => controller.abort(), 5000); // 5-second hard timeout
 *
 * const response = await fetchWithRetry(
 *   'https://api.example.com/slow',
 *   { signal: controller.signal },
 *   { retries: 3 }
 * );
 */
async function fetchWithRetry(
  url,
  options = {},
  {
    retries    = 3,
    baseDelay  = 300,
    maxDelay   = 10_000,
    jitter     = 100,
    retryOn    = [429, 500, 502, 503, 504],
    onRetry    = null,
  } = {}
) {
  // ─── Input validation ────────────────────────────────────────────────────────
  if (!url) {
    throw new TypeError('fetchWithRetry: `url` is required.');
  }
  if (typeof retries !== 'number' || retries < 0 || !Number.isInteger(retries)) {
    throw new TypeError('fetchWithRetry: `retries` must be a non-negative integer.');
  }

  // ─── Helpers ─────────────────────────────────────────────────────────────────

  /**
   * Calculates the delay before the next retry attempt.
   * Formula: min(baseDelay * 2^attempt, maxDelay) + random jitter
   *
   * @param {number} attempt - Zero-based attempt index.
   * @returns {number} Delay in milliseconds.
   */
  const getDelay = (attempt) => {
    const exponential = baseDelay * Math.pow(2, attempt);
    const capped      = Math.min(exponential, maxDelay);
    const randomJitter = Math.random() * jitter;
    return capped + randomJitter;
  };

  /**
   * Returns a Promise that resolves after `ms` milliseconds.
   * Respects an optional AbortSignal so sleep is interrupted on abort.
   *
   * @param {number} ms - Milliseconds to wait.
   * @param {AbortSignal|undefined} signal - Optional abort signal.
   * @returns {Promise<void>}
   */
  const sleep = (ms, signal) =>
    new Promise((resolve, reject) => {
      const timer = setTimeout(resolve, ms);

      if (signal) {
        const onAbort = () => {
          clearTimeout(timer);
          reject(new DOMException('Request aborted during retry delay.', 'AbortError'));
        };
        // Clean up listener once the timer fires normally
        signal.addEventListener('abort', onAbort, { once: true });
      }
    });

  // ─── Retry loop ───────────────────────────────────────────────────────────────
  let lastError  = null;
  let lastResponse = null;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, options);

      // Successful response — return immediately
      if (!retryOn.includes(response.status)) {
        return response;
      }

      // Retryable HTTP status code
      lastResponse = response;
      lastError    = new Error(
        `HTTP ${response.status} ${response.statusText} — ${url}`
      );

    } catch (error) {
      // Never retry an intentional abort
      if (error.name === 'AbortError') {
        throw error;
      }

      lastError    = error;
      lastResponse = null;
    }

    // No more retries left — break out and throw
    if (attempt === retries) {
      break;
    }

    // ── Notify caller before sleeping ──────────────────────────────────────────
    if (typeof onRetry === 'function') {
      onRetry(attempt + 1, lastError, lastResponse);
    }

    // ── Wait before next attempt ───────────────────────────────────────────────
    const delay = getDelay(attempt);
    await sleep(delay, options.signal);
  }

  // All attempts exhausted
  throw lastError;
}
```

---

## Delay Schedule (default settings)

| Attempt | Formula              | Delay (before jitter) |
|---------|----------------------|-----------------------|
| 1st retry | 300 × 2⁰ = 300 ms  | ~300 ms               |
| 2nd retry | 300 × 2¹ = 600 ms  | ~600 ms               |
| 3rd retry | 300 × 2² = 1200 ms | ~1200 ms              |
| nth retry | min(300 × 2ⁿ, 10 000) | capped at 10 s     |

---

## Usage Examples

```javascript
// ── 1. Simple GET ─────────────────────────────────────────────────────────────
const res  = await fetchWithRetry('https://api.example.com/users');
const data = await res.json();

// ── 2. POST with body ─────────────────────────────────────────────────────────
const res = await fetchWithRetry(
  'https://api.example.com/orders',
  {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ item: 'book', qty: 2 }),
  },
  { retries: 4, baseDelay: 500 }
);

// ── 3. Abort after 8 seconds (no retries after abort) ─────────────────────────
const controller = new AbortController();
setTimeout(() => controller.abort(), 8_000);

const res = await fetchWithRetry(
  'https://api.example.com/slow-endpoint',
  { signal: controller.signal },
  { retries: 3 }
);

// ── 4. Structured logging via onRetry ─────────────────────────────────────────
const res = await fetchWithRetry(
  'https://api.example.com/data',
  {},
  {
    retries: 3,
    onRetry: (attempt, error, response) => {
      console.warn({
        message : `Retrying request (attempt ${attempt})`,
        reason  : error?.message,
        status  : response?.status ?? 'network error',
        url     : 'https://api.example.com/data',
      });
    },
  }
);

// ── 5. Error handling ─────────────────────────────────────────────────────────
try {
  const res = await fetchWithRetry('https://api.example.com/flaky', {}, { retries: 3 });
  return await res.json();
} catch (err) {
  if (err.name === 'AbortError') {
    console.error('Request was cancelled.');
  } else {
    console.error('All retries exhausted:', err.message);
  }
}
```

---

## Key Design Decisions

| Decision | Rationale |
|---|---|
| **Exponential backoff** | Avoids hammering a struggling server; gives it time to recover |
| **Jitter** | Prevents thundering-herd when many clients retry at the same time |
| **`maxDelay` cap** | Prevents unbounded wait times in long retry chains |
| **AbortError passthrough** | Intentional cancellations should never be silently retried |
| **`retryOn` whitelist** | Only retries known-transient codes; avoids retrying `400 Bad Request` |
| **`onRetry` callback** | Keeps the function pure while allowing external logging/metrics |
| **Sleep respects signal** | Abort during a backoff delay is honoured immediately |

# `fetchWithRetry` — Fetch with Exponential Backoff Retry

## Overview

A robust wrapper around the native `fetch` API that automatically retries failed requests using exponential backoff with optional jitter, giving transient network issues time to resolve before giving up.

---

## Implementation

```javascript
/**
 * Fetches a URL with automatic retry logic using exponential backoff.
 *
 * Retry behavior:
 *  - Retries on network errors (e.g., DNS failure, connection refused).
 *  - Retries on configurable HTTP status codes (default: 429, 500, 502, 503, 504).
 *  - Does NOT retry on client errors (4xx) unless explicitly listed in `retryOn`.
 *  - Delay between retries: baseDelay * 2^attempt ± jitter (milliseconds).
 *
 * @param {string|URL}  url                          - The resource URL to fetch.
 * @param {RequestInit} [options={}]                 - Standard fetch options (method, headers, body, etc.).
 * @param {object}      [retryOptions={}]            - Configuration for retry behavior.
 * @param {number}      [retryOptions.retries=3]     - Maximum number of retry attempts (not counting the initial request).
 * @param {number}      [retryOptions.baseDelay=300] - Base delay in ms before the first retry. Doubles each attempt.
 * @param {number}      [retryOptions.maxDelay=10000]- Upper cap on delay between retries (ms).
 * @param {boolean}     [retryOptions.jitter=true]   - Add randomness to delay to avoid thundering herd.
 * @param {number[]}    [retryOptions.retryOn=[429, 500, 502, 503, 504]]
 *                                                   - HTTP status codes that should trigger a retry.
 * @param {Function}    [retryOptions.onRetry]       - Optional callback invoked before each retry.
 *                                                     Receives ({ attempt, error, response, delay }).
 *
 * @returns {Promise<Response>} Resolves with the fetch Response on success.
 *
 * @throws {FetchRetryError} When all attempts are exhausted. The error contains:
 *   - `message`  — Human-readable description.
 *   - `attempts` — Total number of attempts made.
 *   - `cause`    — The last Error or Response that caused the failure.
 *
 * @example
 * // Basic usage — 3 retries with defaults
 * const response = await fetchWithRetry('https://api.example.com/data');
 * const data = await response.json();
 *
 * @example
 * // POST request with custom retry settings and a callback
 * const response = await fetchWithRetry(
 *   'https://api.example.com/submit',
 *   {
 *     method: 'POST',
 *     headers: { 'Content-Type': 'application/json' },
 *     body: JSON.stringify({ key: 'value' }),
 *   },
 *   {
 *     retries: 5,
 *     baseDelay: 500,
 *     maxDelay: 15000,
 *     retryOn: [429, 500, 503],
 *     onRetry: ({ attempt, delay, response }) => {
 *       console.warn(`Retry ${attempt} after ${delay}ms — status: ${response?.status}`);
 *     },
 *   }
 * );
 */

// ─── Custom Error ────────────────────────────────────────────────────────────

class FetchRetryError extends Error {
  /**
   * @param {string}          message  - Error description.
   * @param {number}          attempts - Total attempts made (initial + retries).
   * @param {Error|Response}  cause    - The last error or non-OK Response.
   */
  constructor(message, attempts, cause) {
    super(message);
    this.name = "FetchRetryError";
    this.attempts = attempts;
    this.cause = cause; // native Error cause support (Node 16.9+, modern browsers)
  }
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Returns a promise that resolves after `ms` milliseconds.
 * @param {number} ms
 * @returns {Promise<void>}
 */
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Calculates the delay for a given attempt using exponential backoff.
 * Formula: min(baseDelay * 2^attempt, maxDelay) ± up to 20% jitter.
 *
 * @param {number}  attempt   - Zero-based retry attempt index.
 * @param {number}  baseDelay - Base delay in ms.
 * @param {number}  maxDelay  - Maximum delay cap in ms.
 * @param {boolean} jitter    - Whether to add random jitter.
 * @returns {number} Delay in milliseconds.
 */
const calcDelay = (attempt, baseDelay, maxDelay, jitter) => {
  const exponential = Math.min(baseDelay * 2 ** attempt, maxDelay);
  if (!jitter) return exponential;

  // ±20% jitter to spread out concurrent retries
  const jitterAmount = exponential * 0.2 * (Math.random() * 2 - 1);
  return Math.max(0, Math.round(exponential + jitterAmount));
};

// ─── Core Function ───────────────────────────────────────────────────────────

async function fetchWithRetry(url, options = {}, retryOptions = {}) {
  const {
    retries = 3,
    baseDelay = 300,
    maxDelay = 10_000,
    jitter = true,
    retryOn = [429, 500, 502, 503, 504],
    onRetry = null,
  } = retryOptions;

  // Validate inputs early to surface mistakes immediately
  if (typeof url !== "string" && !(url instanceof URL)) {
    throw new TypeError(`fetchWithRetry: 'url' must be a string or URL, got ${typeof url}`);
  }
  if (!Number.isInteger(retries) || retries < 0) {
    throw new TypeError(`fetchWithRetry: 'retries' must be a non-negative integer, got ${retries}`);
  }
  if (typeof baseDelay !== "number" || baseDelay < 0) {
    throw new TypeError(`fetchWithRetry: 'baseDelay' must be a non-negative number, got ${baseDelay}`);
  }

  const totalAttempts = retries + 1; // 1 initial + N retries
  let lastError = null;
  let lastResponse = null;

  for (let attempt = 0; attempt < totalAttempts; attempt++) {
    try {
      const response = await fetch(url, options);

      // ── Success ──────────────────────────────────────────────────────────
      if (response.ok || !retryOn.includes(response.status)) {
        /*
         * Return immediately if:
         *   a) Response is OK (2xx), OR
         *   b) Status code is not in the retryOn list (e.g., 400 Bad Request
         *      is a client error — retrying won't help, so surface it now).
         */
        return response;
      }

      // ── Retryable HTTP error ──────────────────────────────────────────────
      lastResponse = response;
      lastError = new Error(`HTTP ${response.status} ${response.statusText}`);

    } catch (networkError) {
      // ── Network-level failure (no response received) ──────────────────────
      lastError = networkError;
      lastResponse = null;
    }

    // ── Schedule retry or give up ─────────────────────────────────────────
    const isLastAttempt = attempt === totalAttempts - 1;

    if (isLastAttempt) break; // exhausted — fall through to throw

    const delay = calcDelay(attempt, baseDelay, maxDelay, jitter);

    // Notify caller before sleeping
    if (typeof onRetry === "function") {
      onRetry({
        attempt: attempt + 1,   // 1-based for human readability
        totalAttempts,
        error: lastError,
        response: lastResponse,
        delay,
      });
    }

    await sleep(delay);
  }

  // ── All attempts exhausted ────────────────────────────────────────────────
  throw new FetchRetryError(
    `fetchWithRetry: all ${totalAttempts} attempt(s) failed for ${url}. ` +
    `Last error: ${lastError?.message}`,
    totalAttempts,
    lastError ?? lastResponse
  );
}
```

---

## Usage Examples

### 1. Simple GET with defaults
```javascript
try {
  const res = await fetchWithRetry("https://api.example.com/users");
  const users = await res.json();
  console.log(users);
} catch (err) {
  if (err instanceof FetchRetryError) {
    console.error(`Failed after ${err.attempts} attempts:`, err.message);
  }
}
```

### 2. POST with custom retry config
```javascript
const res = await fetchWithRetry(
  "https://api.example.com/orders",
  {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ item: "book", qty: 2 }),
  },
  {
    retries: 4,
    baseDelay: 500,   // 500ms → 1s → 2s → 4s (before jitter)
    maxDelay: 8000,
    retryOn: [429, 500, 503],
    onRetry: ({ attempt, totalAttempts, delay, response }) => {
      console.warn(
        `[Retry ${attempt}/${totalAttempts - 1}] ` +
        `Status: ${response?.status ?? "network error"} — ` +
        `waiting ${delay}ms`
      );
    },
  }
);
```

### 3. Respecting `Retry-After` header (advanced)
```javascript
const res = await fetchWithRetry(url, options, {
  retries: 3,
  onRetry: ({ response }) => {
    // You can read headers in the callback for logging/metrics
    const retryAfter = response?.headers.get("Retry-After");
    if (retryAfter) console.log(`Server requests retry after: ${retryAfter}s`);
  },
});
```

---

## Retry Delay Schedule

With `baseDelay: 300ms`, `maxDelay: 10000ms`, and `jitter: false`:

| Attempt | Formula         | Delay   |
|---------|-----------------|---------|
| 1st retry | 300 × 2⁰    | 300 ms  |
| 2nd retry | 300 × 2¹    | 600 ms  |
| 3rd retry | 300 × 2²    | 1200 ms |
| 4th retry | 300 × 2³    | 2400 ms |
| 5th retry | 300 × 2⁴    | 4800 ms |
| 6th retry | min(9600, 10000) | 9600 ms |

With `jitter: true`, each value is randomly adjusted by ±20%.

---

## Design Decisions

| Decision | Rationale |
|---|---|
| **Don't retry 4xx by default** | Client errors (bad request, unauthorized) won't be fixed by retrying — only retry server/rate-limit errors |
| **Jitter enabled by default** | Prevents [thundering herd](https://en.wikipedia.org/wiki/Thundering_herd_problem) when many clients retry simultaneously |
| **`maxDelay` cap** | Prevents unbounded waits in high-retry scenarios |
| **`onRetry` callback** | Keeps the function pure while giving callers full observability |
| **Custom `FetchRetryError`** | Distinguishes retry exhaustion from other errors and carries diagnostic metadata |

