  } = retryOptions;

  // Validate inputs early to surface mistakes immediately
  if (typeof url !== "string" && !(url instanceof URL)) {
    throw new TypeError(`fetchWithRetry: 'url' must be a string or URL, got ${typeof url}`);
  }
  if (!Number.isInteger(retries) || retries < 0) {
    throw new TypeError(`fetchWithRetry: 'retries' must be a non-negative integer, got ${retries}`);
  }
  if (typeof baseDelay !== "number" || baseDelay < 0) {
    throw new TypeError(`fetchWithRetry: 'baseDelay' must be a non-negative number, got ${baseDelay}`);
  }

  let lastError = null;
  let lastResponse = null;
  const totalAttempts = retries + 1; // initial request + retries

  for (let attempt = 0; attempt < totalAttempts; attempt++) {
    try {
      const response = await fetch(url, options);

      // Success — return immediately
      if (response.ok || !retryOn.includes(response.status)) {
        return response;
      }

      // Retryable HTTP status — treat as a soft failure
      lastResponse = response;

      // If this was the last attempt, stop here (no sleep needed)
      if (attempt === totalAttempts - 1) break;

      const delay = computeDelay(attempt, baseDelay, maxDelay, jitter);

      if (typeof onRetry === "function") {
        onRetry({ attempt: attempt + 1, error: null, response, delay });
      }

      await sleep(delay);

    } catch (error) {
      // Network-level error (no response received)
      lastError = error;

      // If this was the last attempt, stop here
      if (attempt === totalAttempts - 1) break;

      const delay = computeDelay(attempt, baseDelay, maxDelay, jitter);

      if (typeof onRetry === "function") {
        onRetry({ attempt: attempt + 1, error, response: null, delay });
      }

      await sleep(delay);
    }
  }

  // All attempts exhausted — throw a descriptive error
  const cause = lastError ?? lastResponse;
  const reason = lastError
    ? `Network error: ${lastError.message}`
    : `HTTP ${lastResponse.status} (${lastResponse.statusText})`;

  throw new FetchRetryError(
    `fetchWithRetry failed after ${totalAttempts} attempt(s). Last failure — ${reason}`,
    totalAttempts,
    cause
  );
}
