## Design Decisions

| Decision | Rationale |
|---|---|
| **Exponential backoff** | Avoids hammering a struggling server; gives it time to recover |
| **Jitter (±20%)** | Prevents [thundering herd](https://en.wikipedia.org/wiki/Thundering_herd_problem) when many clients retry simultaneously |
| **`maxDelay` cap** | Prevents unreasonably long waits on many retries |
| **Only retry specific status codes** | 400 Bad Request or 404 Not Found will never succeed on retry — no point retrying them |
| **`onRetry` callback** | Enables logging, metrics, or custom delay logic without forking the function |
| **`FetchRetryError` class** | Preserves both the last network error and last HTTP response for rich error handling |
| **`AbortSignal` passthrough** | Callers retain full control over cancellation and timeouts via standard `fetch` options |

# `fetchWithRetry` — Fetch with Exponential Backoff Retry

## Overview

A robust wrapper around the native `fetch` API that automatically retries failed requests using exponential backoff with optional jitter, giving transient network issues time to resolve before giving up.

---

## Implementation

```javascript
/**
 * Fetches a URL with automatic retry logic using exponential backoff.
 *
 * Retry behavior:
 *  - Retries on network errors (e.g., DNS failure, connection refused).
 *  - Retries on configurable HTTP status codes (default: 429, 500, 502, 503, 504).
 *  - Does NOT retry on client errors (4xx) unless explicitly listed in `retryOn`.
 *  - Delay between retries: baseDelay * 2^attempt ± jitter (milliseconds).
 *
 * @param {string|URL}  url                          - The resource URL to fetch.
 * @param {RequestInit} [options={}]                 - Standard fetch options (method, headers, body, etc.).
 * @param {object}      [retryOptions={}]            - Configuration for retry behavior.
 * @param {number}      [retryOptions.retries=3]     - Maximum number of retry attempts (not counting the initial request).
 * @param {number}      [retryOptions.baseDelay=300] - Base delay in ms before the first retry. Doubles each attempt.
 * @param {number}      [retryOptions.maxDelay=10000]- Upper cap on delay between retries (ms).
 * @param {boolean}     [retryOptions.jitter=true]   - Add randomness to delay to avoid thundering herd.
 * @param {number[]}    [retryOptions.retryOn=[429, 500, 502, 503, 504]]
 *                                                   - HTTP status codes that should trigger a retry.
 * @param {Function}    [retryOptions.onRetry]       - Optional callback invoked before each retry.
 *                                                     Receives ({ attempt, error, response, delay }).
 *
 * @returns {Promise<Response>} Resolves with the fetch Response on success.
 *
 * @throws {FetchRetryError} When all attempts are exhausted. The error contains:
 *   - `message`  — Human-readable description.
 *   - `attempts` — Total number of attempts made.
 *   - `cause`    — The last Error or Response that caused the failure.
 *
 * @example
 * // Basic usage — 3 retries with defaults
 * const response = await fetchWithRetry('https://api.example.com/data');
 * const data = await response.json();
 *
 * @example
 * // POST request with custom retry settings and a callback
 * const response = await fetchWithRetry(
 *   'https://api.example.com/submit',
 *   {
 *     method: 'POST',
 *     headers: { 'Content-Type': 'application/json' },
 *     body: JSON.stringify({ key: 'value' }),
 *   },
 *   {
 *     retries: 5,
 *     baseDelay: 500,
 *     maxDelay: 15000,
 *     retryOn: [429, 500, 503],
 *     onRetry: ({ attempt, delay, response }) => {
 *       console.warn(`Retry ${attempt} in ${delay}ms — status: ${response?.status}`);
 *     },
 *   }
 * );
 */

// ─── Custom Error ────────────────────────────────────────────────────────────

class FetchRetryError extends Error {
  /**
   * @param {string}          message  - Error description.
   * @param {number}          attempts - Total attempts made (initial + retries).
   * @param {Error|Response}  cause    - The last error or non-OK Response.
   */
  constructor(message, attempts, cause) {
    super(message);
    this.name = "FetchRetryError";
    this.attempts = attempts;
    this.cause = cause; // native Error cause support (Node 16.9+, modern browsers)
  }
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Returns a promise that resolves after `ms` milliseconds.
 * @param {number} ms
 * @returns {Promise<void>}
 */
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Calculates the delay for a given attempt using exponential backoff.
 *
 * Formula: min(baseDelay * 2^attempt, maxDelay) ± jitter
 *
 * @param {number}  attempt   - Zero-based attempt index (0 = first retry).
 * @param {number}  baseDelay - Base delay in ms.
 * @param {number}  maxDelay  - Maximum delay cap in ms.
 * @param {boolean} jitter    - Whether to add random jitter.
 * @returns {number} Delay in milliseconds.
 */
const calculateDelay = (attempt, baseDelay, maxDelay, jitter) => {
  const exponential = Math.min(baseDelay * 2 ** attempt, maxDelay);
  if (!jitter) return exponential;

  // Full jitter: random value in [0, exponential]
  // Spreads retries across the window to reduce server load spikes.
  return Math.floor(Math.random() * exponential);
};

/**
 * Reads the `Retry-After` header (if present) and returns the wait time in ms.
 * Supports both delta-seconds ("120") and HTTP-date ("Wed, 21 Oct 2025 07:28:00 GMT").
 *
 * @param {Response} response
 * @returns {number|null} Milliseconds to wait, or null if header is absent/invalid.
 */
const parseRetryAfter = (response) => {
  const header = response?.headers?.get("Retry-After");
  if (!header) return null;

  const seconds = Number(header);
  if (!isNaN(seconds)) return seconds * 1000;

  const date = new Date(header);
  if (!isNaN(date.getTime())) return Math.max(0, date.getTime() - Date.now());

  return null;
};

// ─── Core Function ────────────────────────────────────────────────────────────

async function fetchWithRetry(url, options = {}, retryOptions = {}) {
  const {
    retries = 3,
    baseDelay = 300,
    maxDelay = 10_000,
    jitter = true,
    retryOn = [429, 500, 502, 503, 504],
    onRetry = null,
  } = retryOptions;

  // Total attempts = 1 initial + N retries
  const maxAttempts = retries + 1;

  let lastError = null;
  let lastResponse = null;

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    try {
      const response = await fetch(url, options);

      // ── Success ──────────────────────────────────────────────────────────
      if (!retryOn.includes(response.status)) {
        return response; // Caller handles non-retryable 4xx errors themselves
      }

      // ── Retryable HTTP status ─────────────────────────────────────────────
      lastResponse = response;
      lastError = null;

      // If this was the last attempt, stop here
      if (attempt === maxAttempts - 1) break;

      // Respect server's Retry-After header (e.g., rate limiting)
      const retryAfterMs = parseRetryAfter(response);
      const backoffDelay = calculateDelay(attempt, baseDelay, maxDelay, jitter);
      const delay = retryAfterMs !== null
        ? Math.min(retryAfterMs, maxDelay)
        : backoffDelay;

      onRetry?.({ attempt: attempt + 1, error: null, response, delay });
      await sleep(delay);

    } catch (error) {
      // ── Network / fetch error (no response received) ───────────────────
      lastError = error;
      lastResponse = null;

      if (attempt === maxAttempts - 1) break;

      const delay = calculateDelay(attempt, baseDelay, maxDelay, jitter);
      onRetry?.({ attempt: attempt + 1, error, response: null, delay });
      await sleep(delay);
    }
  }

  // ── All attempts exhausted ────────────────────────────────────────────────
  const cause = lastError ?? lastResponse;
  const reason = lastError
    ? `Network error: ${lastError.message}`
    : `HTTP ${lastResponse.status} ${lastResponse.statusText}`;

  throw new FetchRetryError(
    `fetchWithRetry failed after ${maxAttempts} attempt(s): ${reason}`,
    maxAttempts,
    cause
  );
}
```

