 *   - `message`  — Human-readable description.
 *   - `attempts` — Total number of attempts made.
 *   - `cause`    — The last Error or Response that caused the failure.
 *
 * @example
 * // Basic usage — 3 retries with defaults
 * const response = await fetchWithRetry('https://api.example.com/data');
 * const data = await response.json();
 *
 * @example
 * // POST request with custom retry settings and a callback
 * const response = await fetchWithRetry(
 *   'https://api.example.com/submit',
 *   {
 *     method: 'POST',
 *     headers: { 'Content-Type': 'application/json' },
 *     body: JSON.stringify({ key: 'value' }),
 *   },
 *   {
 *     retries: 5,
 *     baseDelay: 500,
 *     maxDelay: 15000,
 *     retryOn: [429, 500, 503],
 *     onRetry: ({ attempt, delay, response }) => {
 *       console.warn(`Retry ${attempt} after ${delay}ms — status: ${response?.status}`);
 *     },
 *   }
 * );
 */

// ─── Custom Error ────────────────────────────────────────────────────────────

class FetchRetryError extends Error {
  /**
   * @param {string}          message  - Error description.
   * @param {number}          attempts - Total attempts made (initial + retries).
   * @param {Error|Response}  cause    - The last error or non-OK Response.
   */
