    super(message);
    this.name = "FetchRetryError";
    this.attempts = attempts;
    this.cause = cause; // native Error cause support (Node 16.9+, modern browsers)
  }
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Returns a promise that resolves after `ms` milliseconds.
 * @param {number} ms
 * @returns {Promise<void>}
 */
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Calculates the delay for a given attempt using exponential backoff.
 *
 * Formula: min(baseDelay * 2^attempt, maxDelay) ± jitter
 *
 * @param {number}  attempt   - Zero-based attempt index (0 = first retry).
 * @param {number}  baseDelay - Base delay in ms.
 * @param {number}  maxDelay  - Maximum delay cap in ms.
 * @param {boolean} jitter    - Whether to add random jitter.
 * @returns {number} Delay in milliseconds.
 */
const calcDelay = (attempt, baseDelay, maxDelay, jitter) => {
  const exponential = Math.min(baseDelay * 2 ** attempt, maxDelay);
  // Jitter: randomize within ±25% of the calculated delay
  const jitterAmount = jitter ? exponential * 0.25 * (Math.random() * 2 - 1) : 0;
  return Math.round(Math.max(0, exponential + jitterAmount));
};

// ─── Core Function ───────────────────────────────────────────────────────────

async function fetchWithRetry(url, options = {}, retryOptions = {}) {
  const {
    retries = 3,
    baseDelay = 300,
    maxDelay = 10_000,
    jitter = true,
    retryOn = [429, 500, 502, 503, 504],
    onRetry = null,
  } = retryOptions;

  // Validate inputs early to surface mistakes immediately
  if (typeof url !== "string" && !(url instanceof URL)) {
    throw new TypeError(`fetchWithRetry: 'url' must be a string or URL, got ${typeof url}`);
  }
  if (!Number.isInteger(retries) || retries < 0) {
    throw new TypeError(`fetchWithRetry: 'retries' must be a non-negative integer, got ${retries}`);
  }
  if (typeof baseDelay !== "number" || baseDelay < 0) {
    throw new TypeError(`fetchWithRetry: 'baseDelay' must be a non-negative number, got ${baseDelay}`);
  }

  const totalAttempts = retries + 1; // initial request + retries
  let lastError = null;
  let lastResponse = null;

  for (let attempt = 0; attempt < totalAttempts; attempt++) {
    try {
      const response = await fetch(url, options);

      // Success — return immediately
      if (!retryOn.includes(response.status)) {
        return response;
      }

      // Retryable HTTP status — treat as a soft failure
      lastResponse = response;
      lastError = null;

      // No more retries left
      if (attempt === totalAttempts - 1) break;

      // Honor Retry-After header if present (common with 429 responses)
      let delay = calcDelay(attempt, baseDelay, maxDelay, jitter);
      const retryAfter = response.headers.get("Retry-After");
      if (retryAfter) {
        const retryAfterMs = parseRetryAfter(retryAfter);
        if (retryAfterMs !== null) {
          delay = Math.min(retryAfterMs, maxDelay);
        }
      }

      onRetry?.({ attempt: attempt + 1, error: null, response, delay });
      await sleep(delay);

    } catch (error) {
      // Network-level error (no response received)
      lastError = error;
      lastResponse = null;

      // No more retries left
      if (attempt === totalAttempts - 1) break;

      const delay = calcDelay(attempt, baseDelay, maxDelay, jitter);
      onRetry?.({ attempt: attempt + 1, error, response: null, delay });
      await sleep(delay);
    }
  }

  // All attempts exhausted — throw a descriptive error
  const cause = lastError ?? lastResponse;
  const reason = lastError
    ? `Network error: ${lastError.message}`
    : `HTTP ${lastResponse.status} ${lastResponse.statusText}`;

  throw new FetchRetryError(
    `fetchWithRetry failed after ${totalAttempts} attempt(s). Last failure: ${reason}`,
    totalAttempts,
    cause
  );
}

// ─── Utility ─────────────────────────────────────────────────────────────────

/**
 * Parses the value of a `Retry-After` HTTP header into milliseconds.
 *
 * Supports two formats:
 *  1. Delta-seconds: `"120"` → 120,000 ms
 *  2. HTTP-date:     `"Wed, 21 Oct 2025 07:28:00 GMT"` → ms until that date
 *
 * @param {string} value - Raw header value.
 * @returns {number|null} Milliseconds to wait, or null if unparseable.
 */
function parseRetryAfter(value) {
  // Format 1: plain integer seconds
  const seconds = Number(value);
  if (!isNaN(seconds) && seconds >= 0) {
    return seconds * 1000;
  }

  // Format 2: HTTP date string
  const date = new Date(value);
  if (!isNaN(date.getTime())) {
    const ms = date.getTime() - Date.now();
    return ms > 0 ? ms : 0;
  }

  return null;
}
