# `fetchWithRetry` — Fetch with Exponential Backoff Retry

## Overview

A robust wrapper around the native `fetch` API that automatically retries failed requests using exponential backoff with optional jitter, giving transient network issues time to resolve before giving up.

---

## Implementation

```javascript
/**
 * Fetches a URL with automatic retry logic using exponential backoff.
 *
 * Retry behavior:
 *  - Retries on network errors (e.g., DNS failure, connection refused).
 *  - Retries on configurable HTTP status codes (default: 429, 500, 502, 503, 504).
 *  - Does NOT retry on client errors (4xx) unless explicitly listed in `retryOn`.
 *  - Delay between retries: baseDelay * 2^attempt ± jitter (milliseconds).
 *
 * @param {string|URL}  url                          - The resource URL to fetch.
 * @param {RequestInit} [options={}]                 - Standard fetch options (method, headers, body, etc.).
 * @param {object}      [retryOptions={}]            - Retry configuration.
 * @param {number}      [retryOptions.retries=3]     - Maximum number of retry attempts (not counting the initial request).
 * @param {number}      [retryOptions.baseDelay=300] - Base delay in ms before the first retry. Doubles each attempt.
 * @param {number}      [retryOptions.maxDelay=10000]- Upper cap on delay between retries (ms).
 * @param {boolean}     [retryOptions.jitter=true]   - Add ±20% random jitter to each delay to avoid thundering herd.
 * @param {number[]}    [retryOptions.retryOn=[429, 500, 502, 503, 504]]
 *                                                   - HTTP status codes that should trigger a retry.
 * @param {Function}    [retryOptions.onRetry]       - Optional callback invoked before each retry.
 *                                                     Signature: (attempt, error, response) => void
 *
 * @returns {Promise<Response>} Resolves with the first successful Response.
 *
 * @throws {Error} Throws the last encountered error after all retries are exhausted.
 *                 If the final failure was an HTTP error (not a network error),
 *                 the thrown error has a `response` property attached.
 *
 * @example
 * // Basic usage — 3 retries with default settings
 * const response = await fetchWithRetry('https://api.example.com/data');
 * const data = await response.json();
 *
 * @example
 * // POST request with custom retry settings and a retry callback
 * const response = await fetchWithRetry(
 *   'https://api.example.com/submit',
 *   {
 *     method: 'POST',
 *     headers: { 'Content-Type': 'application/json' },
 *     body: JSON.stringify({ key: 'value' }),
 *   },
 *   {
 *     retries: 5,
 *     baseDelay: 500,
 *     maxDelay: 15000,
 *     retryOn: [429, 500, 503],
 *     onRetry: (attempt, error, response) => {
 *       console.warn(`Retry #${attempt} — ${error?.message ?? `HTTP ${response?.status}`}`);
 *     },
 *   }
 * );
 */
async function fetchWithRetry(url, options = {}, retryOptions = {}) {
  const {
    retries   = 3,
    baseDelay = 300,
    maxDelay  = 10_000,
    jitter    = true,
    retryOn   = [429, 500, 502, 503, 504],
    onRetry   = null,
  } = retryOptions;

  /**
   * Calculates the delay before the next retry attempt.
   *
   * Formula: min(baseDelay * 2^attempt, maxDelay) ± 20% jitter
   *
   * @param {number} attempt - Zero-based retry attempt index.
   * @returns {number} Delay in milliseconds.
   */
  function getDelay(attempt) {
    const exponential = Math.min(baseDelay * 2 ** attempt, maxDelay);
    if (!jitter) return exponential;

    // ±20% jitter: keeps retries spread out under high concurrency
    const jitterAmount = exponential * 0.2;
    return exponential + Math.random() * jitterAmount * 2 - jitterAmount;
  }

  /**
   * Returns a Promise that resolves after `ms` milliseconds.
   *
   * @param {number} ms - Duration to sleep.
   * @returns {Promise<void>}
   */
  function sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  let lastError;
  let lastResponse;

  // attempt 0 = initial request; attempts 1..retries = retries
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, options);

      // Successful response — return immediately
      if (!retryOn.includes(response.status)) {
        return response;
      }

      // Retryable HTTP status — treat as a soft failure
      lastResponse = response;
      lastError = Object.assign(
        new Error(`HTTP error ${response.status}: ${response.statusText}`),
        { response } // attach response so callers can inspect it
      );

    } catch (networkError) {
      // Hard network failure (offline, DNS, CORS, abort, etc.)
      lastError = networkError;
      lastResponse = null;
    }

    const isLastAttempt = attempt === retries;

    if (!isLastAttempt) {
      const delay = getDelay(attempt);

      // Notify caller before sleeping
      if (typeof onRetry === 'function') {
        onRetry(attempt + 1, lastError, lastResponse);
      }

      await sleep(delay);
    }
  }

  // All attempts exhausted — surface the last error
  throw lastError;
}
