  'https://api.example.com/data',
  {},
  {
    retries: 3,
    onRetry: (attempt, error) => {
      console.warn(`[fetchWithRetry] Attempt ${attempt} failed: ${error.message}`);
    },
  }
);


// ─── 4. Graceful error handling ───────────────────────────────────────────────
