## Key Design Decisions

| Decision | Rationale |
|---|---|
| **Exponential backoff** | Avoids hammering an already-struggling server |
| **Jitter** | Prevents [thundering herd](https://en.wikipedia.org/wiki/Thundering_herd_problem) when many clients retry simultaneously |
| **`maxDelay` cap** | Keeps worst-case wait time predictable |
| **`retryOn` whitelist** | Only retries errors likely to be transient; avoids masking real 4xx bugs |
| **`err.response` attachment** | Lets callers distinguish HTTP failures from network failures after exhaustion |
| **`onRetry` callback** | Keeps retry logic decoupled from logging/monitoring concerns |

# `fetchWithRetry` — Fetch with Exponential Backoff Retry

## Overview

A robust wrapper around the native `fetch` API that automatically retries failed requests using exponential backoff with optional jitter, giving transient network issues time to resolve before giving up.

---

## Implementation

```javascript
/**
 * Fetches a URL with automatic retry logic using exponential backoff.
 *
 * Retry behavior:
 *  - Retries on network errors (e.g., DNS failure, connection refused).
 *  - Retries on configurable HTTP status codes (default: 429, 500, 502, 503, 504).
 *  - Does NOT retry on client errors (4xx) unless explicitly listed in `retryOn`.
 *  - Delay between retries: baseDelay * 2^attempt ± jitter (milliseconds).
 *
 * @param {string|URL}  url                          - The resource URL to fetch.
 * @param {RequestInit} [options={}]                 - Standard fetch options (method, headers, body, etc.).
 * @param {object}      [retryOptions={}]            - Retry configuration.
 * @param {number}      [retryOptions.retries=3]     - Maximum number of retry attempts (not counting the initial request).
 * @param {number}      [retryOptions.baseDelay=300] - Base delay in ms before the first retry. Doubles each attempt.
 * @param {number}      [retryOptions.maxDelay=10000]- Upper cap on delay between retries (ms).
 * @param {boolean}     [retryOptions.jitter=true]   - Add ±20% random jitter to each delay to avoid thundering herd.
 * @param {number[]}    [retryOptions.retryOn=[429, 500, 502, 503, 504]]
 *                                                   - HTTP status codes that should trigger a retry.
 * @param {Function}    [retryOptions.onRetry]       - Optional callback invoked before each retry.
 *                                                     Signature: (attempt, error, response) => void
 *
 * @returns {Promise<Response>} Resolves with the first successful Response.
 *
 * @throws {Error} Throws the last encountered error after all retries are exhausted.
 *                 If the final failure was an HTTP error (not a network error),
 *                 the thrown error has a `response` property containing the Response object.
 *
 * @example
 * // Basic usage — 3 retries with default settings
 * const response = await fetchWithRetry('https://api.example.com/data');
 * const data = await response.json();
 *
 * @example
 * // POST request with custom retry settings and a retry callback
 * const response = await fetchWithRetry(
 *   'https://api.example.com/submit',
 *   {
 *     method: 'POST',
 *     headers: { 'Content-Type': 'application/json' },
 *     body: JSON.stringify({ key: 'value' }),
 *   },
 *   {
 *     retries: 5,
 *     baseDelay: 500,
 *     maxDelay: 15000,
 *     retryOn: [429, 500, 503],
 *     onRetry: (attempt, error, response) => {
 *       console.warn(`Retry #${attempt} — ${error?.message ?? `HTTP ${response?.status}`}`);
 *     },
 *   }
 * );
 */
async function fetchWithRetry(url, options = {}, retryOptions = {}) {
  const {
    retries   = 3,
    baseDelay = 300,
    maxDelay  = 10_000,
    jitter    = true,
    retryOn   = [429, 500, 502, 503, 504],
    onRetry   = null,
  } = retryOptions;

  /**
   * Calculates the delay before the next retry attempt.
   *
   * Formula: min(baseDelay * 2^attempt, maxDelay) ± 20% jitter
   *
   * @param   {number} attempt - Zero-based retry attempt index.
   * @returns {number}           Delay in milliseconds.
   */
  function getDelay(attempt) {
    const exponential = Math.min(baseDelay * 2 ** attempt, maxDelay);
    if (!jitter) return exponential;

    // Apply ±20% jitter
    const jitterRange = exponential * 0.2;
    return exponential + Math.random() * jitterRange * 2 - jitterRange;
  }

  /**
   * Pauses execution for a given number of milliseconds.
   *
   * @param   {number}  ms - Duration to sleep.
   * @returns {Promise<void>}
   */
  function sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  let lastError;

  // attempt 0 = initial request; attempts 1..retries = retries
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, options);

      // Successful response — return immediately
      if (!retryOn.includes(response.status)) {
        return response;
      }

      // Retryable HTTP status — treat as a soft error
      lastError = new Error(`HTTP error: ${response.status} ${response.statusText}`);
      lastError.response = response;

      // No more retries left — throw now
      if (attempt === retries) break;

      onRetry?.(attempt + 1, null, response);

    } catch (networkError) {
      // Hard network failure (offline, DNS, CORS, abort, etc.)
      lastError = networkError;

      if (attempt === retries) break;

      onRetry?.(attempt + 1, networkError, null);
    }

    const delay = getDelay(attempt);
    await sleep(delay);
  }

  throw lastError;
}
```

---

## Behavior at a Glance

| Scenario | Behavior |
|---|---|
| `200 OK` | ✅ Returns `Response` immediately |
| `404 Not Found` | ✅ Returns `Response` immediately (not retried by default) |
| `500 Server Error` | 🔁 Retried up to `retries` times |
| `429 Too Many Requests` | 🔁 Retried with backoff |
| Network offline | 🔁 Retried (caught as `TypeError`) |
| All retries exhausted | ❌ Throws last `Error` (with `.response` if HTTP error) |

---

## Delay Schedule (defaults: `baseDelay=300ms`, `maxDelay=10s`, `jitter=true`)

```
Attempt 1 retry delay:  ~300ms  (300 * 2^0)
Attempt 2 retry delay:  ~600ms  (300 * 2^1)
Attempt 3 retry delay:  ~1200ms (300 * 2^2)
Attempt 4 retry delay:  ~2400ms (300 * 2^3)
Attempt 5 retry delay:  ~4800ms (300 * 2^4)
...capped at maxDelay (10,000ms)
```

---

## Usage Examples

```javascript
// ─── 1. Simple GET ────────────────────────────────────────────────────────────
const res = await fetchWithRetry('https://api.example.com/users');
const users = await res.json();


// ─── 2. Respect Retry-After header on 429 ────────────────────────────────────
const res = await fetchWithRetry(
  'https://api.example.com/data',
  {},
  {
    retries: 4,
    onRetry: (attempt, error, response) => {
      if (response?.status === 429) {
        const retryAfter = response.headers.get('Retry-After');
        console.log(`Rate limited. Server says retry after ${retryAfter}s`);
      }
      console.log(`Retrying... attempt ${attempt}`);
    },
  }
);


// ─── 3. Abort after a total timeout ──────────────────────────────────────────
const controller = new AbortController();
const timeoutId  = setTimeout(() => controller.abort(), 8000); // 8s total budget

try {
  const res = await fetchWithRetry(
    'https://api.example.com/slow',
    { signal: controller.signal },
    { retries: 3, baseDelay: 200 }
  );
  const data = await res.json();
} finally {
  clearTimeout(timeoutId);
}


// ─── 4. Error handling ───────────────────────────────────────────────────────
try {
  const res = await fetchWithRetry('https://api.example.com/flaky', {}, { retries: 3 });
  return await res.json();
} catch (err) {
  if (err.response) {
    // Final failure was an HTTP error response
    console.error(`Failed with status: ${err.response.status}`);
  } else {
    // Final failure was a network/abort error
    console.error(`Network error: ${err.message}`);
  }
}
```

---

## Key Design Decisions

- **`retryOn` whitelist** — Only specific status codes are retried. This prevents silently retrying legitimate `400 Bad Request` or `401 Unauthorized` errors that will never succeed.
- **Jitter** — Prevents the [thundering herd problem](https://en.wikipedia.org/wiki/Thundering_herd_problem) when many clients retry simultaneously after an outage.
- **`err.response` attachment** — Preserves the original `Response` object on the thrown error so callers can inspect headers (e.g., `Retry-After`) or the body even after failure.
- **`AbortSignal` passthrough** — Passes `options` directly to `fetch`, so `AbortController` works natively for total timeout budgets.

# `fetchWithRetry` — Fetch with Exponential Backoff Retry

## Overview

A robust wrapper around the native `fetch` API that automatically retries failed requests using exponential backoff with optional jitter, giving transient network issues time to resolve before giving up.

---

## Implementation

```javascript
/**
 * Fetches a URL with automatic retry logic using exponential backoff.
 *
 * Retry behavior:
 *  - Retries on network errors (e.g., DNS failure, connection refused).
 *  - Retries on configurable HTTP status codes (default: 429, 500, 502, 503, 504).
 *  - Does NOT retry on client errors (4xx) unless explicitly listed in `retryOn`.
 *  - Delay between retries: baseDelay * 2^attempt ± jitter (milliseconds).
 *
 * @param {string|URL}  url                          - The resource URL to fetch.
 * @param {RequestInit} [options={}]                 - Standard fetch options (method, headers, body, etc.).
 * @param {object}      [retryOptions={}]            - Configuration for retry behavior.
 * @param {number}      [retryOptions.retries=3]     - Maximum number of retry attempts (not counting the initial request).
 * @param {number}      [retryOptions.baseDelay=300] - Base delay in ms before the first retry. Doubles each attempt.
 * @param {number}      [retryOptions.maxDelay=10000]- Upper cap on delay between retries (ms).
 * @param {boolean}     [retryOptions.jitter=true]   - Add randomness to delay to avoid thundering herd.
 * @param {number[]}    [retryOptions.retryOn=[429, 500, 502, 503, 504]]
 *                                                   - HTTP status codes that should trigger a retry.
 * @param {Function}    [retryOptions.onRetry]       - Optional callback invoked before each retry.
 *                                                     Receives ({ attempt, error, response, delay }).
 *
 * @returns {Promise<Response>} Resolves with the fetch Response on success.
 *
 * @throws {FetchRetryError} When all attempts are exhausted. The error contains:
 *   - `message`  — Human-readable description.
 *   - `attempts` — Total number of attempts made.
 *   - `cause`    — The last Error or Response that caused the failure.
 *
 * @example
 * // Basic usage — 3 retries with defaults
 * const response = await fetchWithRetry('https://api.example.com/data');
 * const data = await response.json();
 *
 * @example
 * // POST request with custom retry settings and a callback
 * const response = await fetchWithRetry(
 *   'https://api.example.com/submit',
 *   {
 *     method: 'POST',
 *     headers: { 'Content-Type': 'application/json' },
 *     body: JSON.stringify({ key: 'value' }),
 *   },
 *   {
 *     retries: 5,
 *     baseDelay: 500,
 *     maxDelay: 15000,
 *     retryOn: [429, 500, 503],
 *     onRetry: ({ attempt, delay, response }) => {
 *       console.warn(`Retry ${attempt} in ${delay}ms — status: ${response?.status}`);
 *     },
 *   }
 * );
 */

// ─── Custom Error ────────────────────────────────────────────────────────────

class FetchRetryError extends Error {
  /**
   * @param {string}          message  - Error description.
   * @param {number}          attempts - Total attempts made (initial + retries).
   * @param {Error|Response}  cause    - The last error or non-OK Response.
   */
  constructor(message, attempts, cause) {
    super(message);
    this.name = "FetchRetryError";
    this.attempts = attempts;
    this.cause = cause; // native Error cause support (Node 16.9+, modern browsers)
  }
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Returns a promise that resolves after `ms` milliseconds.
 * @param {number} ms
 * @returns {Promise<void>}
 */
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Calculates the delay for a given attempt using exponential backoff.
 * Formula: min(baseDelay * 2^attempt, maxDelay) ± optional jitter
 *
 * @param {number}  attempt   - Zero-based attempt index (0 = first retry).
 * @param {number}  baseDelay - Base delay in ms.
 * @param {number}  maxDelay  - Maximum delay cap in ms.
 * @param {boolean} jitter    - Whether to add random jitter (±20% of computed delay).
 * @returns {number} Delay in milliseconds.
 */
const computeDelay = (attempt, baseDelay, maxDelay, jitter) => {
  const exponential = Math.min(baseDelay * 2 ** attempt, maxDelay);
  if (!jitter) return exponential;

  // Full jitter: random value in [0.8 * exponential, 1.2 * exponential]
  const jitterRange = exponential * 0.2;
  return Math.round(exponential + (Math.random() * 2 - 1) * jitterRange);
};

// ─── Core Function ───────────────────────────────────────────────────────────

async function fetchWithRetry(url, options = {}, retryOptions = {}) {
  const {
    retries = 3,
    baseDelay = 300,
    maxDelay = 10_000,
    jitter = true,
    retryOn = [429, 500, 502, 503, 504],
    onRetry = null,
  } = retryOptions;

  // Validate inputs early to surface mistakes immediately
  if (typeof url !== "string" && !(url instanceof URL)) {
    throw new TypeError(`fetchWithRetry: 'url' must be a string or URL, got ${typeof url}`);
  }
  if (!Number.isInteger(retries) || retries < 0) {
    throw new TypeError(`fetchWithRetry: 'retries' must be a non-negative integer, got ${retries}`);
  }
  if (typeof baseDelay !== "number" || baseDelay < 0) {
    throw new TypeError(`fetchWithRetry: 'baseDelay' must be a non-negative number, got ${baseDelay}`);
  }

  let lastError = null;
  let lastResponse = null;
  const totalAttempts = retries + 1; // initial request + retries

  for (let attempt = 0; attempt < totalAttempts; attempt++) {
    try {
      const response = await fetch(url, options);

      // Success — return immediately
      if (response.ok || !retryOn.includes(response.status)) {
        return response;
      }

      // Retryable HTTP status — treat as a soft failure
      lastResponse = response;

      // If this was the last attempt, stop here (no sleep needed)
      if (attempt === totalAttempts - 1) break;

      const delay = computeDelay(attempt, baseDelay, maxDelay, jitter);

      if (typeof onRetry === "function") {
        onRetry({ attempt: attempt + 1, error: null, response, delay });
      }

      await sleep(delay);

    } catch (error) {
      // Network-level error (no response received)
      lastError = error;

      // If this was the last attempt, stop here
      if (attempt === totalAttempts - 1) break;

      const delay = computeDelay(attempt, baseDelay, maxDelay, jitter);

      if (typeof onRetry === "function") {
        onRetry({ attempt: attempt + 1, error, response: null, delay });
      }

      await sleep(delay);
    }
  }

  // All attempts exhausted — throw a descriptive error
  const cause = lastError ?? lastResponse;
  const reason = lastError
    ? `Network error: ${lastError.message}`
    : `HTTP ${lastResponse.status} (${lastResponse.statusText})`;

  throw new FetchRetryError(
    `fetchWithRetry failed after ${totalAttempts} attempt(s). Last failure — ${reason}`,
    totalAttempts,
    cause
  );
}
```

