## Key Design Decisions

| Decision | Rationale |
|---|---|
| **Exponential backoff** | Avoids hammering a struggling server; gives it time to recover |
| **Jitter** | Prevents synchronized retries from multiple clients hitting at the same time |
| **`retryOn` whitelist** | Only retries *transient* errors; 400/401/403/404 are not retried (they won't self-heal) |
| **`FetchRetryError`** | Distinguishes retry exhaustion from other errors; carries `attempts` and `cause` |
| **`onRetry` callback** | Enables logging, metrics, or custom side-effects without coupling them to the core logic |
| **Input validation** | Fails fast with clear messages instead of cryptic downstream errors |

# `fetchWithRetry` - Fetch with Exponential Backoff Retry

## Overview

A robust wrapper around the native `fetch` API that automatically retries failed requests using exponential backoff with jitter, preventing thundering herd problems in distributed systems.

```javascript
/**
 * Fetches a resource with automatic retry logic using exponential backoff.
 *
 * Retry behavior:
 * - Retries on network errors (no response received)
 * - Retries on configurable HTTP status codes (default: 429, 500, 502, 503, 504)
 * - Does NOT retry on client errors (4xx) unless explicitly configured
 * - Uses exponential backoff: delay = baseDelay * 2^attempt + random jitter
 *
 * @param {string | URL | Request} url
 *   The resource URL to fetch. Accepts the same types as native fetch().
 *
 * @param {RequestInit & FetchWithRetryOptions} [options={}]
 *   Extended fetch options including retry configuration.
 *
 * @param {number} [options.retries=3]
 *   Maximum number of retry attempts after the initial request fails.
 *   Total requests made = retries + 1.
 *   Must be a non-negative integer.
 *
 * @param {number} [options.baseDelay=300]
 *   Base delay in milliseconds before the first retry.
 *   Subsequent retries: baseDelay * 2^attemptNumber + jitter.
 *   Example with baseDelay=300: ~300ms, ~600ms, ~1200ms (+ jitter each time).
 *
 * @param {number} [options.maxDelay=10000]
 *   Maximum delay cap in milliseconds to prevent excessively long waits.
 *   Regardless of the exponential calculation, delay will never exceed this.
 *
 * @param {number[]} [options.retryOn=[429, 500, 502, 503, 504]]
 *   HTTP status codes that should trigger a retry.
 *   Note: Network failures (no response) always trigger a retry.
 *
 * @param {AbortSignal} [options.signal]
 *   AbortSignal to cancel the fetch and all pending retries immediately.
 *   Propagated to every underlying fetch() call.
 *
 * @param {function} [options.onRetry]
 *   Optional callback invoked before each retry attempt.
 *   Useful for logging, metrics, or custom side effects.
 *   @param {number}        onRetry.attempt   - Current retry number (1-based)
 *   @param {number}        onRetry.delay     - Milliseconds to wait before this retry
 *   @param {Error|null}    onRetry.error     - Network error, or null if HTTP error
 *   @param {Response|null} onRetry.response  - HTTP response, or null if network error
 *
 * @returns {Promise<Response>}
 *   Resolves with the first successful Response (status not in retryOn).
 *   Rejects if all attempts are exhausted or the request is aborted.
 *
 * @throws {FetchRetryError}
 *   Custom error containing:
 *   - message:   Human-readable failure summary
 *   - attempts:  Total number of attempts made
 *   - lastError: The underlying Error or Response from the final attempt
 *
 * @throws {DOMException}
 *   With name 'AbortError' if the request was cancelled via AbortSignal.
 *
 * @example
 * // Basic usage — 3 retries with default backoff
 * const response = await fetchWithRetry('https://api.example.com/data');
 * const data = await response.json();
 *
 * @example
 * // Custom retry config with logging
 * const response = await fetchWithRetry(
 *   'https://api.example.com/submit',
 *   {
 *     method: 'POST',
 *     body: JSON.stringify({ key: 'value' }),
 *     headers: { 'Content-Type': 'application/json' },
 *     retries: 5,
 *     baseDelay: 500,
 *     maxDelay: 15000,
 *     retryOn: [429, 500, 503],
 *     onRetry: ({ attempt, delay, error, response }) => {
 *       console.warn(
 *         `Retry ${attempt}: waiting ${delay}ms.`,
 *         error ? `Error: ${error.message}` : `Status: ${response.status}`
 *       );
 *     },
 *   }
 * );
 *
 * @example
 * // Cancellable request
 * const controller = new AbortController();
 * setTimeout(() => controller.abort(), 5000); // cancel after 5s
 *
 * try {
 *   const response = await fetchWithRetry(url, { signal: controller.signal });
 * } catch (err) {
 *   if (err.name === 'AbortError') console.log('Request was cancelled');
 * }
 */

// ─── Custom Error Class ──────────────────────────────────────────────────────

/**
 * Error thrown when all fetch retry attempts are exhausted.
 *
 * @class FetchRetryError
 * @extends {Error}
 *
 * @property {number}           attempts  - Total attempts made (initial + retries)
 * @property {Error|Response}   lastError - The error or response from the final attempt
 */
class FetchRetryError extends Error {
  /**
   * @param {string}         message
   * @param {number}         attempts
   * @param {Error|Response} lastError
   */
  constructor(message, attempts, lastError) {
    super(message);
    this.name = "FetchRetryError";
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Calculates the delay for a given retry attempt using exponential backoff
 * with full jitter to spread out retry storms.
 *
 * Formula: min(maxDelay, baseDelay * 2^attempt) * Math.random()
 * The random factor distributes retries across the full [0, cap] range.
 *
 * @param {number} attempt   - Zero-based attempt index (0 = first retry)
 * @param {number} baseDelay - Base delay in milliseconds
 * @param {number} maxDelay  - Maximum delay cap in milliseconds
 * @returns {number} Delay in milliseconds (always a positive integer)
 *
 * @see https://aws.amazon.com/blogs/architecture/exponential-backoff-and-jitter/
 */
function calculateBackoff(attempt, baseDelay, maxDelay) {
  const exponential = baseDelay * Math.pow(2, attempt);
  const capped = Math.min(maxDelay, exponential);
  const jittered = Math.random() * capped; // "full jitter" strategy
  return Math.max(1, Math.floor(jittered));
}

/**
 * Returns a Promise that resolves after `ms` milliseconds.
 * Rejects immediately if the provided AbortSignal is already aborted,
 * or if it fires during the wait period.
 *
 * @param {number}       ms     - Duration to wait in milliseconds
 * @param {AbortSignal}  signal - Optional signal to cancel the sleep
 * @returns {Promise<void>}
 * @throws {DOMException} With name 'AbortError' if aborted
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      return reject(new DOMException("Request aborted", "AbortError"));
    }

    const timer = setTimeout(resolve, ms);

    signal?.addEventListener(
      "abort",
      () => {
        clearTimeout(timer);
        reject(new DOMException("Request aborted", "AbortError"));
      },
      { once: true }
    );
  });
}

// ─── Core Implementation ─────────────────────────────────────────────────────

async function fetchWithRetry(url, options = {}) {
  // ── Destructure retry-specific options, pass the rest to fetch() ──────────
  const {
    retries = 3,
    baseDelay = 300,
    maxDelay = 10000,
    retryOn = [429, 500, 502, 503, 504],
    onRetry = null,
    signal,
    ...fetchOptions
  } = options;

  // ── Input validation ──────────────────────────────────────────────────────
  if (!Number.isInteger(retries) || retries < 0) {
    throw new RangeError(`'retries' must be a non-negative integer, got: ${retries}`);
  }
  if (typeof baseDelay !== "number" || baseDelay < 0) {
    throw new RangeError(`'baseDelay' must be a non-negative number, got: ${baseDelay}`);
  }
  if (typeof maxDelay !== "number" || maxDelay < baseDelay) {
    throw new RangeError(`'maxDelay' (${maxDelay}) must be >= baseDelay (${baseDelay})`);
  }

  const totalAttempts = retries + 1; // initial request + N retries
  let lastError = null;
  let lastResponse = null;

  for (let attempt = 0; attempt < totalAttempts; attempt++) {
    const isRetry = attempt > 0;

    // ── If this is a retry, wait before re-requesting ─────────────────────
    if (isRetry) {
      const delay = calculateBackoff(attempt - 1, baseDelay, maxDelay);

      // Notify caller before waiting (useful for logging/metrics)
      onRetry?.({
        attempt,          // 1-based retry count
        delay,
        error: lastError,
        response: lastResponse,
      });

      // Honor abort signal during the backoff wait period
      await sleep(delay, signal);
    }

    try {
      const response = await fetch(url, { ...fetchOptions, signal });

      // ── Success: status code is not in the retry list ─────────────────
      if (!retryOn.includes(response.status)) {
        return response; // ✅ Resolved — return to caller
      }

      // ── Retryable HTTP error ──────────────────────────────────────────
      lastResponse = response;
      lastError = null;

      // If this was the final attempt, stop — don't retry anymore
      if (attempt === totalAttempts - 1) break;

    } catch (error) {
      // ── AbortError: do not retry, propagate immediately ───────────────
      if (error.name === "AbortError") throw error;

      // ── Network-level error (DNS failure, timeout, etc.) ──────────────
      lastError = error;
      lastResponse = null;

      // If this was the final attempt, stop
      if (attempt === totalAttempts - 1) break;
    }
  }

  // ── All attempts exhausted: throw descriptive error ──────────────────────
  const failureSource = lastError
    ? `Network error: ${lastError.message}`
    : `HTTP ${lastResponse?.status} ${lastResponse?.statusText}`;

  throw new FetchRetryError(
    `fetchWithRetry failed after ${totalAttempts} attempt(s). ${failureSource}`,
    totalAttempts,
    lastError ?? lastResponse
  );
}
