const res = await fetchWithRetry("https://api.example.com/users");
const users = await res.json();


// ── 2. POST with custom retry config ──────────────────────────────────────
const res = await fetchWithRetry("https://api.example.com/orders", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ item: "book", qty: 2 }),
  retries: 4,
  baseDelay: 200,
  maxDelay: 8000,
});


// ── 3. With logging callback ───────────────────────────────────────────────
const res = await fetchWithRetry("https://api.example.com/data", {
  retries: 3,
  onRetry: ({ attempt, delay, error, response }) => {
    const reason = error?.message ?? `HTTP ${response?.status}`;
    console.warn(`[Retry ${attempt}/3] Waiting ${delay}ms. Reason: ${reason}`);
  },
});


// ── 4. With AbortController (e.g., user navigates away) ───────────────────
const controller = new AbortController();
const timeoutId = setTimeout(() => controller.abort(), 10_000);

try {
  const res = await fetchWithRetry("https://api.example.com/slow", {
    signal: controller.signal,
    retries: 3,
  });
  clearTimeout(timeoutId);
  return await res.json();
} catch (err) {
  if (err.name === "AbortError") {
    console.log("Fetch cancelled (timeout or user action)");
  } else if (err instanceof FetchRetryError) {
    console.error(`Failed after ${err.attempts} attempts:`, err.lastError);
  }
}


// ── 5. Respect Retry-After header from server (advanced) ──────────────────
const res = await fetchWithRetry("https://api.example.com/rate-limited", {
  retries: 3,
  retryOn: [429],
  onRetry: ({ response }) => {
    // You can read Retry-After here for custom logic/logging
    const retryAfter = response?.headers.get("Retry-After");
    if (retryAfter) console.log(`Server requests retry after: ${retryAfter}s`);
  },
});
