// ─── Mock fetch factory ───────────────────────────────────────────────────────

/**
 * Creates a mock fetch function from a sequence of outcomes.
 * Each outcome is either:
 *   { status: number, headers?: object }  → resolves with a Response-like object
 *   { throw: Error }                       → rejects with that error
 */
function mockFetch(outcomes) {
  let callCount = 0;
  const calls = [];

  const fn = async (url, options) => {
    const outcome = outcomes[Math.min(callCount, outcomes.length - 1)];
    calls.push({ url, options, attempt: callCount });
    callCount++;

    if (outcome.throw) throw outcome.throw;

    return {
      status: outcome.status,
      ok: outcome.status >= 200 && outcome.status < 300,
      headers: {
        get: (key) => (outcome.headers?.[key.toLowerCase()] ?? null),
      },
      json: async () => outcome.body ?? {},
    };
  };

  fn.callCount = () => callCount;
  fn.calls     = calls;
  return fn;
}

// Patch global fetch for tests
