async function runTests() {
  console.log('Running fetchWithRetry tests...\n');

  // Test 1: Succeeds on first try
  {
    mockFetch(200);
    const res = await fetchWithRetry('http://test.com');
    console.assert(res.status === 200, '✗ Test 1 failed');
    console.log('✓ Test 1: Succeeds immediately on 200');
  }

  // Test 2: Retries on 503, then succeeds
