    let calls = 0;
    global.fetch = async () => {
      calls++;
      const status = calls < 3 ? 503 : 200;
      return { status, statusText: String(status), ok: status === 200 };
    };
    const res = await fetchWithRetry('http://test.com', {}, {
      retries: 3,
      baseDelay: 10, // fast for tests
    });
    console.assert(res.status === 200, '✗ Test 2 failed: wrong status');
    console.assert(calls === 3, `✗ Test 2 failed: expected 3 calls, got ${calls}`);
    console.log('✓ Test 2: Retries on 503, succeeds on 3rd attempt');
  }

  // Test 3: Exhausts all retries and throws HTTP error
  {
