    const res = await fetchWithRetry('http://test.com', {}, { retries: 3, baseDelay: 10 });
    console.assert(calls === 1, `✗ Test 4 failed: expected 1 call, got ${calls}`);
    console.assert(res.status === 404, '✗ Test 4 failed: wrong status');
    console.log('✓ Test 4: Does not retry non-retryable 404');
  }

  // Test 5: Retries on network error, then succeeds
  {
