      if (calls < 3) throw new Error('Network failure');
      return { status: 200, statusText: 'OK', ok: true };
    };
    const res = await fetchWithRetry('http://test.com', {}, { retries: 3, baseDelay: 10 });
    console.assert(res.status === 200, '✗ Test 5 failed');
    console.log('✓ Test 5: Retries on network error, succeeds on 3rd attempt');
  }

