## Usage Examples

### 1. Basic GET request

```javascript
try {
  const res = await fetchWithRetry('https://api.example.com/users');
  const users = await res.json();
  console.log(users);
} catch (err) {
  console.error('All retries failed:', err.message);
  // If the last failure was an HTTP error, the raw response is attached:
  if (err.response) {
    console.error('Final status:', err.response.status);
  }
}
```

### 2. POST with a JSON body

```javascript
const response = await fetchWithRetry(
  'https://api.example.com/orders',
  {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ item: 'widget', qty: 3 }),
  },
  { retries: 4, initialDelay: 250 }
);
```

### 3. Combined timeout + retry

```javascript
// Abort the entire operation (including wait time) after 15 seconds
const controller = new AbortController();
const timeout = setTimeout(() => controller.abort(), 15_000);

try {
  const res = await fetchWithRetry(
    'https://slow-api.example.com/data',
    { signal: controller.signal },
    { retries: 3, initialDelay: 1000 }
  );
  console.log(await res.json());
} finally {
  clearTimeout(timeout);
}
```

---

## Behavior Summary

| Scenario | Behavior |
|---|---|
| Network error (no response) | Always retried |
| Status in `retryOn` | Retried up to `retries` times |
| Status **not** in `retryOn` | Returned immediately (success) |
| `Retry-After` header present | Waits the server-specified duration |
| `AbortError` | Re-thrown immediately, no retry |
| All retries exhausted | Throws last error (with `.response` if HTTP) |

---

## Key Design Decisions

| Decision | Rationale |
|---|---|
| **Jitter on backoff** | Prevents [thundering herd](https://en.wikipedia.org/wiki/Thundering_herd_problem) when many clients retry simultaneously |
| **`Retry-After` support** | Respects server-side rate limiting signals (especially for 429s) |
| **`AbortSignal` threading** | Cancels both the in-flight fetch *and* the sleep between retries |
| **`.response` on error** | Lets callers inspect the final failed response without swallowing it |
| **`retryOn` whitelist** | Avoids retrying definitive client errors (400, 401, 403, 404) by default |

# `fetchWithRetry` — Fetch with Exponential Backoff Retry

## Overview

A robust wrapper around the native `fetch` API that automatically retries failed requests using exponential backoff with jitter, giving transient failures time to resolve before each subsequent attempt.

```javascript
/**
 * Fetches a resource with automatic retry logic using exponential backoff.
 *
 * Retry behavior:
 *  - Retries on network errors (e.g., DNS failure, connection refused).
 *  - Retries on server errors (HTTP 5xx) and 429 (Too Many Requests).
 *  - Does NOT retry on client errors (HTTP 4xx, except 429).
 *  - Delay between retries: baseDelay * 2^attempt + random jitter (ms).
 *
 * @param {string|URL}  url              - The resource URL to fetch.
 * @param {RequestInit} [options={}]     - Standard fetch options (method, headers, body, etc.).
 * @param {object}      [retryConfig={}] - Configuration for retry behavior.
 * @param {number}      [retryConfig.retries=3]        - Maximum number of retry attempts.
 * @param {number}      [retryConfig.baseDelay=300]    - Base delay in ms before the first retry.
 * @param {number}      [retryConfig.maxDelay=10000]   - Maximum delay in ms between retries.
 * @param {number}      [retryConfig.backoffFactor=2]  - Multiplier applied to delay each retry.
 * @param {Set<number>} [retryConfig.retryOn]          - HTTP status codes that trigger a retry.
 *                                                        Defaults to 5xx codes + 429.
 * @param {AbortSignal} [retryConfig.signal]           - AbortSignal to cancel all retries.
 * @param {Function}    [retryConfig.onRetry]          - Callback invoked before each retry.
 *                                                        Receives ({ attempt, delay, error, response }).
 *
 * @returns {Promise<Response>} Resolves with the successful fetch Response.
 *
 * @throws {FetchRetryError} When all attempts are exhausted or the request is aborted.
 *
 * @example
 * // Basic usage
 * const response = await fetchWithRetry('https://api.example.com/data');
 * const data = await response.json();
 *
 * @example
 * // POST with custom retry config and progress logging
 * const response = await fetchWithRetry(
 *   'https://api.example.com/submit',
 *   {
 *     method: 'POST',
 *     headers: { 'Content-Type': 'application/json' },
 *     body: JSON.stringify({ key: 'value' }),
 *   },
 *   {
 *     retries: 5,
 *     baseDelay: 500,
 *     maxDelay: 15000,
 *     onRetry: ({ attempt, delay, error }) => {
 *       console.warn(`Retry ${attempt} in ${delay}ms — ${error?.message}`);
 *     },
 *   }
 * );
 *
 * @example
 * // Cancellable request
 * const controller = new AbortController();
 * setTimeout(() => controller.abort(), 5000); // Cancel after 5s
 *
 * const response = await fetchWithRetry(
 *   'https://api.example.com/slow',
 *   {},
 *   { signal: controller.signal, retries: 10 }
 * );
 */

// ─── Custom Error ────────────────────────────────────────────────────────────

/**
 * Error thrown when fetchWithRetry exhausts all attempts or is aborted.
 * Carries the last error/response for inspection.
 */
class FetchRetryError extends Error {
  /**
   * @param {string}         message          - Human-readable error description.
   * @param {object}         details
   * @param {number}         details.attempts - Total attempts made (initial + retries).
   * @param {Error|null}     details.lastError - Last network-level error, if any.
   * @param {Response|null}  details.lastResponse - Last HTTP response, if any.
   */
  constructor(message, { attempts, lastError, lastResponse }) {
    super(message);
    this.name = 'FetchRetryError';
    this.attempts = attempts;
    this.lastError = lastError;
    this.lastResponse = lastResponse;
  }
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Returns a promise that resolves after `ms` milliseconds.
 * Rejects immediately if the provided AbortSignal is already aborted
 * or fires during the wait.
 *
 * @param {number}       ms     - Milliseconds to wait.
 * @param {AbortSignal}  signal - Optional signal to cancel the delay.
 * @returns {Promise<void>}
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      return reject(new DOMException('Aborted', 'AbortError'));
    }

    const timer = setTimeout(resolve, ms);

    signal?.addEventListener('abort', () => {
      clearTimeout(timer);
      reject(new DOMException('Aborted', 'AbortError'));
    }, { once: true });
  });
}

/**
 * Calculates the delay before the next retry attempt using
 * exponential backoff capped at `maxDelay`, plus random jitter
 * to avoid thundering-herd problems when many clients retry simultaneously.
 *
 * Formula: min(baseDelay * backoffFactor^attempt, maxDelay) + jitter
 *
 * @param {number} attempt       - Zero-based retry attempt index.
 * @param {number} baseDelay     - Starting delay in ms.
 * @param {number} maxDelay      - Upper bound for delay in ms.
 * @param {number} backoffFactor - Exponential growth multiplier.
 * @returns {number} Delay in milliseconds.
 */
function calcDelay(attempt, baseDelay, maxDelay, backoffFactor) {
  const exponential = baseDelay * Math.pow(backoffFactor, attempt);
  const capped = Math.min(exponential, maxDelay);
  const jitter = Math.random() * 0.2 * capped; // ±0–20% jitter
  return Math.round(capped + jitter);
}

/**
 * Determines whether an HTTP response status code should trigger a retry.
 *
 * @param {number}   status  - HTTP status code.
 * @param {Set<number>} retryOn - Set of status codes considered retryable.
 * @returns {boolean}
 */
function isRetryableStatus(status, retryOn) {
  return retryOn.has(status) || (status >= 500 && status <= 599);
}

// ─── Default Config ───────────────────────────────────────────────────────────

const DEFAULT_RETRY_ON = new Set([
  429, // Too Many Requests
  500, // Internal Server Error
  502, // Bad Gateway
  503, // Service Unavailable
  504, // Gateway Timeout
]);

const DEFAULT_CONFIG = {
  retries: 3,
  baseDelay: 300,     // ms
  maxDelay: 10_000,   // ms
  backoffFactor: 2,
  retryOn: DEFAULT_RETRY_ON,
  signal: null,
  onRetry: null,
};

// ─── Main Function ────────────────────────────────────────────────────────────

async function fetchWithRetry(url, options = {}, retryConfig = {}) {
  // Merge caller config with defaults
  const config = { ...DEFAULT_CONFIG, ...retryConfig };
  const {
    retries,
    baseDelay,
    maxDelay,
    backoffFactor,
    retryOn,
    signal,
    onRetry,
  } = config;

  // Validate inputs
  if (typeof url !== 'string' && !(url instanceof URL)) {
    throw new TypeError('`url` must be a string or URL instance.');
  }
  if (!Number.isInteger(retries) || retries < 0) {
    throw new RangeError('`retries` must be a non-negative integer.');
  }
  if (baseDelay < 0 || maxDelay < 0) {
    throw new RangeError('`baseDelay` and `maxDelay` must be non-negative.');
  }

  const totalAttempts = retries + 1; // initial attempt + retries
  let lastError = null;
  let lastResponse = null;

  for (let attempt = 0; attempt < totalAttempts; attempt++) {
    // Honour external cancellation before each attempt
    if (signal?.aborted) {
      throw new FetchRetryError('Request aborted before attempt.', {
        attempts: attempt,
        lastError,
        lastResponse,
      });
    }

    try {
      // Merge the caller's signal with our retry signal so either can cancel
      const response = await fetch(url, { ...options, signal });

      // Successful response — return immediately
      if (!isRetryableStatus(response.status, retryOn)) {
        return response;
      }

      // Retryable HTTP status — treat response as a soft failure
      lastResponse = response;
      lastError = new Error(`HTTP ${response.status} ${response.statusText}`);

    } catch (error) {
      // AbortError is never retried — propagate immediately
      if (error.name === 'AbortError') {
        throw new FetchRetryError('Request was aborted.', {
          attempts: attempt + 1,
          lastError: error,
          lastResponse,
        });
      }

      // Network-level error (e.g., no connection) — eligible for retry
      lastError = error;
    }

    // ── No more retries left ──────────────────────────────────────────────
    const isLastAttempt = attempt === totalAttempts - 1;
    if (isLastAttempt) break;

    // ── Schedule next retry ───────────────────────────────────────────────
    const delay = calcDelay(attempt, baseDelay, maxDelay, backoffFactor);

    // Notify caller before we wait
    if (typeof onRetry === 'function') {
      onRetry({
        attempt: attempt + 1,   // 1-based for readability in logs
        delay,
        error: lastError,
        response: lastResponse,
      });
    }

    await sleep(delay, signal);
  }

  // All attempts exhausted
  throw new FetchRetryError(
    `All ${totalAttempts} attempt(s) failed for ${url}.`,
    { attempts: totalAttempts, lastError, lastResponse }
  );
}
```

