 * @throws {DOMException}
 *   With name "AbortError" if the provided AbortSignal fires.
 *
 * @example
 * // Basic usage — 3 retries with default settings
 * const response = await fetchWithRetry('https://api.example.com/data');
 * const data = await response.json();
 *
 * @example
 * // POST request with custom retry settings and logging
 * const response = await fetchWithRetry(
 *   'https://api.example.com/submit',
 *   {
 *     method: 'POST',
 *     headers: { 'Content-Type': 'application/json' },
 *     body: JSON.stringify({ key: 'value' }),
 *   },
 *   {
 *     retries: 5,
 *     baseDelay: 500,
 *     maxDelay: 15000,
 *     retryOn: [429, 500, 503],
 *     onRetry: (attempt, error, response) => {
 *       console.warn(
 *         `Retry ${attempt}: ${error?.message ?? `HTTP ${response.status}`}`
 *       );
 *     },
 *   }
 * );
 *
 * @example
 * // With AbortController for timeout-based cancellation
 * const controller = new AbortController();
 * const timeoutId = setTimeout(() => controller.abort(), 8000);
 *
 * try {
 *   const response = await fetchWithRetry(
 *     'https://api.example.com/slow',
 *     { signal: controller.signal },
 *     { retries: 3 }
 *   );
 *   const data = await response.json();
 * } finally {
 *   clearTimeout(timeoutId);
 * }
 */
async function fetchWithRetry(url, options = {}, retryOptions = {}) {
  // ─── Validate inputs ────────────────────────────────────────────────────────
  if (typeof url !== "string" && !(url instanceof URL)) {
    throw new TypeError(`fetchWithRetry: 'url' must be a string or URL instance, got ${typeof url}`);
  }

  // ─── Destructure retry configuration with defaults ───────────────────────
  const {
    retries   = 3,
    baseDelay = 300,
    maxDelay  = 10_000,
    jitter    = 100,
    retryOn   = [429, 500, 502, 503, 504],
    onRetry   = null,
  } = retryOptions;

  // ─── Internal helpers ────────────────────────────────────────────────────────

  /**
   * Calculates the delay for a given attempt using exponential backoff + jitter.
   *
   * Formula: min(baseDelay * 2^attempt, maxDelay) + random(0, jitter)
   *
   * @param {number} attempt - Zero-based attempt index (0 = first retry)
   * @returns {number} Delay in milliseconds
   */
  function calculateDelay(attempt) {
    const exponential = baseDelay * Math.pow(2, attempt);
    const capped      = Math.min(exponential, maxDelay);
    const noise       = Math.random() * jitter;
    return capped + noise;
  }

  /**
   * Returns a Promise that resolves after `ms` milliseconds.
   * Rejects immediately if the AbortSignal fires during the wait.
   *
   * @param {number} ms
   * @param {AbortSignal|undefined} signal
   * @returns {Promise<void>}
   */
  function delay(ms, signal) {
    return new Promise((resolve, reject) => {
      // If already aborted before we even start waiting, reject immediately
      if (signal?.aborted) {
        return reject(new DOMException("Fetch aborted", "AbortError"));
      }

      const timeoutId = setTimeout(resolve, ms);

      // Clean up the timer and reject if the signal fires during the delay
      signal?.addEventListener(
        "abort",
        () => {
          clearTimeout(timeoutId);
          reject(new DOMException("Fetch aborted", "AbortError"));
        },
        { once: true }
      );
    });
  }

  // ─── Retry loop ───────────────────────────────────────────────────────────
  let lastError    = null;
  let lastResponse = null;

  // Total attempts = initial attempt + retries
  for (let attempt = 0; attempt <= retries; attempt++) {
    // If this is a retry (not the first attempt), wait with backoff first
    if (attempt > 0) {
      const waitMs = calculateDelay(attempt - 1); // attempt-1 keeps delays 0-indexed

      // Invoke optional callback before waiting so callers can log immediately
      if (typeof onRetry === "function") {
        onRetry(attempt, lastError, lastResponse);
      }

      // Await the backoff delay (respects AbortSignal)
      await delay(waitMs, options.signal);
    }

    try {
      const response = await fetch(url, options);

      // If the status code is NOT in the retry list, we're done — success or
      // a non-retryable failure (e.g. 400 Bad Request)
      if (!retryOn.includes(response.status)) {
        return response;
      }

      // Status code is retryable — store it and loop if attempts remain
      lastResponse = response;
      lastError    = null;

      // If we've exhausted all retries, throw a descriptive error
      if (attempt === retries) {
        throw new Error(
          `fetchWithRetry: Request failed after ${retries + 1} attempt(s). ` +
          `Last status: ${response.status} ${response.statusText} — ${url}`
        );
      }

    } catch (error) {
      // Never retry an AbortError — the caller explicitly cancelled
      if (error.name === "AbortError") {
        throw error;
      }

      lastError    = error;
      lastResponse = null;

      // If we've exhausted all retries, re-throw the last network error
      if (attempt === retries) {
        error.message =
          `fetchWithRetry: Request failed after ${retries + 1} attempt(s). ` +
          `Last error: ${error.message} — ${url}`;
        throw error;
      }

      // Otherwise, the loop continues to the next attempt
    }
  }
}
