 * //     { name: "Linus", team: "engineering" }
 * //   ],
 * //   research: [
 * //     { name: "Grace", team: "research" }
 * //   ]
 * // }
 *
 * @example
 * const nums = [1, 2, 3, 4, 5, 6];
 * const byParity = groupBy(nums, n => (n % 2 === 0 ? "even" : "odd"));
 * // { odd: [1, 3, 5], even: [2, 4, 6] }
 */
function groupBy(arr, keyFn) {
  return arr.reduce((groups, item, index, array) => {
    const key = keyFn(item, index, array);

    if (!groups[key]) {
      groups[key] = [];
    }

    groups[key].push(item);
    return groups;
  }, /** @type {Record<PropertyKey, any[]>} */ ({}));
}
