/**
 * Fetch a URL with retry support and exponential backoff.
 *
 * Retries are attempted when:
 * - `fetch()` throws (e.g. network failure, DNS error, timeout via AbortController)
 * - the response is not `ok` (status outside 200–299)
 *
 * Backoff timing:
 * - Attempt 1: immediate
 * - Attempt 2: wait 500ms
 * - Attempt 3: wait 1000ms
 * - Attempt 4: wait 2000ms
 * - ...doubling each retry
 *
 * @param {string} url
 *   The resource URL to request.
 *
 * @param {RequestInit} [options={}]
 *   Standard fetch options such as method, headers, body, signal, etc.
 *
 * @param {number} [retries=3]
 *   Number of retries after the initial attempt.
 *   Example:
 *   - retries = 0 -> 1 total attempt
 *   - retries = 3 -> up to 4 total attempts
 *
 * @returns {Promise<Response>}
 *   Resolves with a successful `Response` object.
 *
 * @throws {Error}
 *   Throws the last encountered error if all attempts fail.
 *   For non-OK HTTP responses, throws an Error with `status` and `response`
 *   attached for easier handling.
 *
 * @example
 * const response = await fetchWithRetry("https://api.example.com/data", {}, 3);
 * const data = await response.json();
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  const baseDelay = 500;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, options);

      if (!response.ok) {
        const error = new Error(`Request failed with status ${response.status}`);
        error.status = response.status;
        error.response = response;
        throw error;
      }

      return response;
    } catch (error) {
      const isLastAttempt = attempt === retries;

      if (isLastAttempt) {
        throw error;
      }

      const delay = baseDelay * 2 ** attempt;
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }
}
