/**
 * Fetch a URL with automatic retries and exponential backoff.
 *
 * Retries are attempted when:
 * - `fetch()` throws (for example, network failure, DNS issues, timeout via AbortController)
 * - the response has a non-OK status (`response.ok === false`)
 *
 * Backoff strategy:
 * - wait `baseDelay` ms before the first retry
 * - double the delay after each failed attempt
 * - example with baseDelay=500 and retries=3:
 *   - initial attempt: immediately
 *   - retry 1: wait 500ms
 *   - retry 2: wait 1000ms
 *   - retry 3: wait 2000ms
 *
 * @param {string|URL} url
 *   The resource to fetch.
 *
 * @param {Object} [options={}]
 *   Standard `fetch` options, plus optional retry settings:
 *
 * @param {number} [options.baseDelay=500]
 *   Initial delay in milliseconds before the first retry.
 *
 * @param {function} [options.shouldRetry]
 *   Optional callback to decide whether a retry should occur.
 *   Signature:
 *     ({ error, response, attempt, retriesLeft }) => boolean
 *
 *   Where:
 *   - `error` is set if `fetch()` threw
 *   - `response` is set if a response was received
 *   - `attempt` is the current failed attempt number (starting at 1)
 *   - `retriesLeft` is how many retries remain
 *
 *   If omitted:
 *   - thrown errors are retried
 *   - non-OK responses are retried
 *
 * @param {number} [retries=3]
 *   Number of retries after the initial attempt.
 *   For example, `retries=3` means up to 4 total attempts.
 *
 * @returns {Promise<Response>}
 *   Resolves with a successful `Response`.
 *   Rejects with the last error encountered, or throws an Error for the final non-OK response.
 *
 * @example
 * const res = await fetchWithRetry("https://api.example.com/data", {}, 3);
 * const data = await res.json();
 *
 * @example
 * // Custom retry policy: retry only on 5xx or thrown network errors
 * const res = await fetchWithRetry("https://api.example.com/data", {
 *   baseDelay: 300,
 *   shouldRetry: ({ error, response, retriesLeft }) => {
 *     if (retriesLeft <= 0) return false;
 *     if (error) return true;
 *     return response && response.status >= 500;
 *   }
 * }, 4);
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  const {
    baseDelay = 500,
    shouldRetry,
    ...fetchOptions
  } = options;

  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

  const defaultShouldRetry = ({ error, response, retriesLeft }) => {
    if (retriesLeft <= 0) return false;
    if (error) return true;
    if (response && !response.ok) return true;
    return false;
  };

  const retryDecider = shouldRetry || defaultShouldRetry;

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, fetchOptions);

      if (response.ok) {
        return response;
      }

      const retriesLeft = retries - attempt;
      const shouldTryAgain = retryDecider({
        error: null,
        response,
        attempt: attempt + 1,
        retriesLeft
      });

      if (!shouldTryAgain) {
        throw new Error(`Request failed with status ${response.status} ${response.statusText}`);
      }

      if (attempt < retries) {
        const delay = baseDelay * 2 ** attempt;
        await sleep(delay);
        continue;
      }

      throw new Error(`Request failed after retries with status ${response.status} ${response.statusText}`);
    } catch (error) {
      lastError = error;

      const retriesLeft = retries - attempt;
      const shouldTryAgain = retryDecider({
        error,
        response: null,
        attempt: attempt + 1,
        retriesLeft
      });

      if (!shouldTryAgain || attempt >= retries) {
        throw lastError;
      }

      const delay = baseDelay * 2 ** attempt;
      await sleep(delay);
    }
  }

  throw lastError || new Error("fetchWithRetry failed unexpectedly");
}
```

