 *   Initial backoff delay in milliseconds.
 *
 * @param {function} [options.shouldRetry]
 *   Optional custom retry predicate:
 *   `(error, response, attempt) => boolean`
 *
 *   - `error`: the thrown fetch error, or `null`
 *   - `response`: the fetch response, or `null`
 *   - `attempt`: current retry attempt number (1-based)
 *
 *   Return `true` to retry, `false` to stop.
 *
 * @param {number} [retries=3]
 *   Maximum number of retry attempts after the initial request.
 *   For example:
 *   - retries = 0 -> one total request
 *   - retries = 3 -> up to four total requests
 *
 * @returns {Promise<Response>}
 *   Resolves with a successful `Response`.
 *
 * @throws {Error}
 *   Throws the last fetch error, or an error describing the final failed response.
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  const {
    baseDelay = 500,
    shouldRetry,
    ...fetchOptions
  } = options;

  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, fetchOptions);

      if (response.ok) {
        return response;
      }

      const retryAllowed = attempt < retries;
      const customDecision = shouldRetry
        ? shouldRetry(null, response, attempt + 1)
        : true;

      if (!retryAllowed || !customDecision) {
        throw new Error(
          `Request failed with status ${response.status} ${response.statusText}`
        );
      }
    } catch (error) {
      lastError = error;

      const retryAllowed = attempt < retries;
      const customDecision = shouldRetry
        ? shouldRetry(error, null, attempt + 1)
        : true;

      if (!retryAllowed || !customDecision) {
        throw lastError;
      }
    }

    const delay = baseDelay * 2 ** attempt;
    await sleep(delay);
  }

  throw lastError || new Error("Request failed after retries");
