 *   An object whose properties are the group keys and whose values are arrays
 *   containing the items that mapped to that key.
 *
 * @example
 * const users = [
 *   { name: "Ada", role: "admin" },
 *   { name: "Bob", role: "user" },
 *   { name: "Eve", role: "admin" },
 * ];
 *
 * const grouped = groupBy(users, user => user.role);
 * // {
 * //   admin: [{ name: "Ada", role: "admin" }, { name: "Eve", role: "admin" }],
 * //   user: [{ name: "Bob", role: "user" }]
 * // }
 *
 * @example
 * groupBy([1, 2, 3, 4], n => (n % 2 === 0 ? "even" : "odd"));
 * // { odd: [1, 3], even: [2, 4] }
 */
function groupBy(arr, keyFn) {
  const result = {};

  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    const key = keyFn(item, i, arr);

    // Initialize the group on first encounter.
    if (!Object.prototype.hasOwnProperty.call(result, key)) {
      result[key] = [];
    }

    result[key].push(item);
  }

  return result;
