/**
 * Groups the elements of an array by a key derived from each element.
 *
 * @template T - The type of items in the input array.
 * @template K - The type of the grouping key. Must be usable as a Map key.
 *
 * @param arr - The array of items to group.
 * @param keyFn - A function that receives each item and returns its grouping key.
 *
 * @returns A `Map` where each key maps to an array of items that produced that key.
 *
 * @example
 * const users = [
 *   { name: "Alice", role: "admin" },
 *   { name: "Bob", role: "user" },
 *   { name: "Carol", role: "admin" },
 * ];
 *
 * const grouped = groupBy(users, u => u.role);
 * // Map {
 * //   "admin" => [{ name: "Alice", role: "admin" }, { name: "Carol", role: "admin" }],
 * //   "user"  => [{ name: "Bob", role: "user" }]
 * // }
 */
export function groupBy<T, K>(arr: T[], keyFn: (item: T) => K): Map<K, T[]> {
  const result = new Map<K, T[]>();

  for (const item of arr) {
    const key = keyFn(item);
    const bucket = result.get(key);

    if (bucket) {
      bucket.push(item);
    } else {
      result.set(key, [item]);
    }
  }

  return result;
}
