/**
 * Fetch a URL with automatic retries using exponential backoff.
 *
 * Retries are attempted when:
 * - `fetch()` rejects (network errors, CORS issues, etc.)
 * - or when the response is not `ok` (status outside the 200–299 range), if you enable that behavior
 *
 * Default behavior below retries on both thrown errors and non-OK responses.
 *
 * @param {string | URL | Request} url - The resource to fetch.
 * @param {RequestInit} [options={}] - Standard fetch options.
 * @param {number} [retries=3] - Number of retry attempts after the initial request.
 * @returns {Promise<Response>} A promise that resolves with the successful Response.
 *
 * @example
 * const res = await fetchWithRetry("https://api.example.com/data", {}, 3);
 * const data = await res.json();
 *
 * @example
 * // POST with custom headers
 * const res = await fetchWithRetry(
 *   "/api/save",
 *   {
 *     method: "POST",
 *     headers: { "Content-Type": "application/json" },
 *     body: JSON.stringify({ name: "Alice" })
 *   },
 *   5
 * );
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  const initialDelayMs = 300;   // starting backoff delay
  const maxDelayMs = 10_000;    // cap the delay so it doesn't grow without bound

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, options);

      // Treat non-2xx responses as failures worth retrying.
      // If you only want retries on network errors, remove this block.
      if (!response.ok) {
        throw new Error(`HTTP ${response.status} ${response.statusText}`);
      }

      return response;
    } catch (error) {
      lastError = error;

      // If we've used all retries, rethrow the last error.
      if (attempt === retries) break;

      // Exponential backoff: 300ms, 600ms, 1200ms, 2400ms, ...
      const delayMs = Math.min(initialDelayMs * 2 ** attempt, maxDelayMs);

      await sleep(delayMs);
    }
  }

  throw lastError;
}

/**
 * Pause execution for a given number of milliseconds.
 *
 * @param {number} ms
 * @returns {Promise<void>}
 */
function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}
