 * - Calls `fetch(url, options)`.
 * - If `fetch()` rejects (for example, network error), it retries.
 * - Waits `100ms * 2^attempt` before each retry:
 *   - 1st retry: 100ms
 *   - 2nd retry: 200ms
 *   - 3rd retry: 400ms
 *   - etc.
 * - Stops after `retries` additional attempts.
 *
 * Notes:
 * - This implementation retries only on thrown/rejected errors.
 * - `fetch()` does not reject for HTTP error statuses like 404 or 500;
 *   it resolves with a `Response`. If you want to retry on certain HTTP
 *   statuses, you can add that logic where indicated below.
 *
 * @param {string | Request} url - The request URL or Request object.
 * @param {RequestInit} [options={}] - Standard fetch options.
 * @param {number} [retries=3] - Number of retry attempts after the initial call.
 * @returns {Promise<Response>} Resolves with the successful fetch Response.
 * @throws {Error} Re-throws the last error if all attempts fail.
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  const baseDelay = 100;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, options);

      // Uncomment this block if you want to retry on HTTP errors too:
      // if (!response.ok) {
      //   throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      // }

      return response;
    } catch (error) {
      if (attempt === retries) {
        throw error;
      }

      const delay = baseDelay * 2 ** attempt;
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }
