 *   The URL or Request object to fetch.
 *
 * @param {RequestInit} [options={}]
 *   Standard fetch options, such as:
 *   - method
 *   - headers
 *   - body
 *   - signal
 *
 * @param {number} [retries=3]
 *   Number of retry attempts after the initial request fails.
 *   Example: `retries = 3` means up to 4 total attempts.
 *
 * @returns {Promise<Response>}
 *   Resolves with the final successful `Response`, or rejects with the last error.
 *
 * @example
 * const res = await fetchWithRetry("https://api.example.com/data", {
 *   method: "GET",
 * }, 3);
 * const data = await res.json();
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  const baseDelay = options.baseDelay ?? 300; // ms
  const retryOnStatus = options.retryOnStatus ?? []; // e.g. [500, 502, 503, 504]

  // Avoid passing custom retry settings to fetch itself.
  const {
    baseDelay: _baseDelay,
    retryOnStatus: _retryOnStatus,
    ...fetchOptions
  } = options;

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, fetchOptions);

      // Optional: retry on certain HTTP status codes
      if (retryOnStatus.includes(response.status) && attempt < retries) {
        lastError = new Error(`HTTP ${response.status} ${response.statusText}`);
      } else {
        return response;
      }
    } catch (err) {
      lastError = err;
    }

    // Wait before next retry, except after the final attempt
    if (attempt < retries) {
      const delay = baseDelay * Math.pow(2, attempt);
      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }

  throw lastError;
