/**
 * Groups the elements of an array according to a specified key.
 * 
 * It iterates over each element, applies a function to derive a key,
 * and collects all elements with the same key into an array.
 *
 * @template T The type of the elements in the array.
 * @param {Array<T>} arr The array to process.
 * @param {(item: T) => string | number} keyFn The function to execute on each element to derive the grouping key.
 * @returns {Object.<string, Array<T>>} An object where keys are the derived group keys and values are arrays of the corresponding elements.
 *
 * @example
 * // 1. Grouping an array of objects by a property
 * const people = [
 *   { name: 'Alice', city: 'New York' },
 *   { name: 'Bob', city: 'Chicago' },
 *   { name: 'Charlie', city: 'New York' }
 * ];
 *
 * const peopleByCity = groupBy(people, person => person.city);
 * // Result:
 * // {
 * //   "New York": [
 * //     { name: 'Alice', city: 'New York' },
 * //     { name: 'Charlie', city: 'New York' }
 * //   ],
 * //   "Chicago": [
 * //     { name: 'Bob', city: 'Chicago' }
 * //   ]
 * // }
 *
 * @example
 * // 2. Grouping an array of numbers by a calculation
 * const numbers = [6.1, 4.2, 6.3, 1.2, 4.4];
 *
 * const numbersByInteger = groupBy(numbers, Math.floor);
 * // Result:
 * // {
 * //   "6": [6.1, 6.3],
 * //   "4": [4.2, 4.4],
 * //   "1": [1.2]
 * // }
 * 
 * @example
 * // 3. Grouping strings by their length
 * const words = ["one", "two", "three", "four", "five"];
 * const wordsByLength = groupBy(words, word => word.length);
 * // Result:
 * // {
 * //   "3": ["one", "two"],
 * //   "5": ["three"],
 * //   "4": ["four", "five"]
 * // }
 */
function groupBy(arr, keyFn) {
  return arr.reduce((acc, item) => {
    // Get the key for the current item
    const key = keyFn(item);

    // If this key doesn't exist in the accumulator, create it with an empty array
    if (!acc[key]) {
      acc[key] = [];
    }

    // Push the current item to the array for this key
    acc[key].push(item);

    // Return the accumulator for the next iteration
    return acc;
  }, {}); // Start with an empty object as the initial accumulator
