/**
 * Fetches a resource with a specified number of retries using exponential backoff.
 *
 * This function wraps the standard `fetch` API to provide resilience against
 * temporary network issues or server-side failures. It only retries on
 * network errors or 5xx server responses. Client-side errors (4xx) are not retried.
 *
 * @param {string | URL | Request} url The resource to fetch. This is the first argument to `fetch`.
 * @param {object} [options={}] An object containing any custom settings that you want to apply to the request. This is the second argument to `fetch`.
 * @param {number} [retries=3] The number of times to retry after the initial failed attempt. A value of 3 means up to 4 total attempts.
 * @param {number} [baseDelay=1000] The base delay in milliseconds for the first retry. Subsequent retries will double this delay.
 * @returns {Promise<Response>} A promise that resolves with the `Response` object if the fetch is successful.
 * @throws {Error} Throws an error if all fetch attempts fail. The error will be the one from the final attempt.
 */
async function fetchWithRetry(url, options = {}, retries = 3, baseDelay = 1000) {
  // The loop will run for the initial attempt + the number of retries.
  for (let i = 0; i <= retries; i++) {
    try {
      const response = await fetch(url, options);

      // If the response is ok (status in the range 200-299), we're done.
      if (response.ok) {
        return response;
      }

      // If the status is a server error (5xx), we should retry.
      // We throw an error to be caught by the catch block.
      if (response.status >= 500 && response.status < 600) {
        throw new Error(`Server error: ${response.status} ${response.statusText}`);
      }

      // For any other non-ok response (e.g., 4xx client errors),
      // we don't retry. We return the response for the caller to handle.
      console.error(`Client error: ${response.status} ${response.statusText}. Not retrying.`);
      return response;

    } catch (error) {
      // This block catches network errors and the server errors we threw above.
      const isLastAttempt = i === retries;
      if (isLastAttempt) {
        console.error(`All ${retries + 1} attempts failed. Last error:`, error);
        // Re-throw the last error to be caught by the caller.
        throw error;
      }

      // Calculate delay with exponential backoff and jitter.
      // Jitter adds a small random amount of time to prevent synchronized retries.
      const jitter = Math.random() * 500; // 0-500ms of randomness
      const delay = Math.pow(2, i) * baseDelay + jitter;

      console.warn(
        `Attempt ${i + 1} failed. Retrying in ${Math.round(delay)}ms...`
      );

      // Wait for the calculated delay before the next attempt.
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }
}


