 * @param {RequestInit} [options] An object containing any custom settings that you want to apply to the request. This is the same as the second argument to `fetch`.
 * @param {number} [retries=3] The number of times to retry the request after the initial attempt fails.
 * @param {number} [baseDelayMs=1000] The base delay in milliseconds for the first retry. Each subsequent retry will double this delay.
 * @returns {Promise<Response>} A Promise that resolves with the `Response` object if the request is successful.
 * @throws {Error} An error if the request fails after all retry attempts have been exhausted. The error will be the one from the last attempt.
 *
 * @example
 * async function getUserData() {
 *   const url = 'https://api.example.com/data';
 *   const options = {
 *     headers: { 'Authorization': 'Bearer your-token' }
 *   };
 *
 *   try {
 *     // Try fetching the data, with 3 retries on failure
 *     const response = await fetchWithRetry(url, options, 3);
 *
 *     if (!response.ok) {
 *       // Handle non-successful responses (e.g., 404 Not Found) that weren't retried
 *       console.error(`HTTP error! Status: ${response.status}`);
 *       return null;
 *     }
 *
 *     const data = await response.json();
 *     console.log('Successfully fetched data:', data);
 *     return data;
 *   } catch (error) {
 *     // This block will be reached if all retries fail
 *     console.error('Failed to fetch data after multiple retries:', error);
 *     return null;
 *   }
 * }
 *
 * getUserData();
 */
async function fetchWithRetry(url, options = {}, retries = 3, baseDelayMs = 1000) {
  let lastError;

  // The loop runs for the initial attempt (i=0) plus the number of retries.
  for (let i = 0; i <= retries; i++) {
    try {
      if (i > 0) {
        // Calculate delay for retries.
        // The delay is baseDelay * 2^i (e.g., 1000, 2000, 4000, ...)
        const delay = baseDelayMs * Math.pow(2, i - 1);

        // Add jitter to prevent thundering herd problem.
        // Jitter is a random value between -50% and +50% of the delay.
        const jitter = delay * (Math.random() - 0.5);
        const totalDelay = delay + jitter;

        console.log(`Attempt ${i} failed. Retrying in ${Math.round(totalDelay)}ms...`);

        // Wait for the calculated delay before the next attempt.
        await new Promise(resolve => setTimeout(resolve, totalDelay));
      }

      const response = await fetch(url, options);

      // If the response is successful (200-299), return it.
      if (response.ok) {
        return response;
      }

      // If it's a server error (500-599), we should retry.
      // We throw an error to be caught by the catch block, triggering the retry logic.
      if (response.status >= 500 && response.status <= 599) {
        throw new Error(`Server error: ${response.status} ${response.statusText}`);
      }

      // For any other non-ok response (e.g., 4xx client errors),
      // we don't retry. We return the response immediately for the caller to handle.
      return response;

    } catch (error) {
      // Store the error from the latest attempt.
      // This will be a network error or the server error we threw above.
      lastError = error;
    }
  }

  // If the loop completes without a successful response, throw the last captured error.
  throw lastError;
}
