   * @param {string} message - The error message.
   * @param {Response} response - The original Response object from the fetch call.
   */
  constructor(message, response) {
    super(message);
    this.name = 'HTTPError';
    this.response = response;
  }
}

/**
 * Fetches a resource with a specified number of retries using an exponential backoff strategy.
 * This is useful for handling transient network errors or temporary server-side issues (e.g., 5xx status codes).
 *
 * The delay between retries increases exponentially and includes a "jitter" (a random factor)
 * to prevent clients from retrying in synchronized waves (thundering herd problem).
 *
 * @param {string | URL | Request} url - The URL to fetch.
 * @param {RequestInit} [options={}] - The options object for the fetch call (e.g., method, headers, body).
 * @param {number} [retries=3] - The maximum number of retries to attempt after the initial call fails.
 * @returns {Promise<Response>} A promise that resolves with the Response object on success.
 * @throws {HTTPError | Error} Throws an `HTTPError` for failed HTTP statuses (like 4xx or 5xx after all retries)
 * or a standard `Error` for network failures after all retries.
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  // The base delay in milliseconds for the first retry.
  const baseDelay = 1000; // 1 second
  // The random "jitter" to add to the delay, preventing synchronized retries.
  const jitter = 500; // 0.5 seconds

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, options);

      // If the response is successful (status in the 200-299 range), return it.
      if (response.ok) {
        console.log(`Attempt ${attempt + 1} succeeded for ${url}`);
        return response;
      }

      // For server errors (5xx), we should retry.
      // For client errors (4xx), we should not retry, as the request is likely invalid.
      if (response.status >= 500 && response.status <= 599) {
        // Throw an error to be caught by the catch block and trigger a retry.
        throw new HTTPError(`Server error: ${response.status} ${response.statusText}`, response);
      } else {
        // For 4xx errors, throw and fail immediately without retrying.
        throw new HTTPError(`Client error: ${response.status} ${response.statusText}`, response);
      }

    } catch (error) {
      console.error(`Attempt ${attempt + 1} failed for ${url}. Error: ${error.message}`);

      // If it's the last attempt or a non-retriable error, re-throw the error.
      if (attempt === retries || (error instanceof HTTPError && error.response.status < 500)) {
        throw error;
      }

      // Calculate the delay for the next retry with exponential backoff and jitter.
      // Formula: (baseDelay * 2^attempt) + random(0, jitter)
      const delay = baseDelay * Math.pow(2, attempt) + Math.random() * jitter;

      console.log(`Retrying in ${Math.round(delay)}ms...`);

      // Wait for the calculated delay before the next attempt.
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }
