 * @param {number} ms - The number of milliseconds to wait.
 * @returns {Promise<void>} A promise that resolves after the specified delay.
 */
const wait = (ms) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Fetches a resource from a URL with a specified number of retries on failure,
 * using an exponential backoff strategy with jitter to avoid overwhelming the server.
 *
 * A "failure" is defined as either a network error (fetch promise rejects) or an
 * HTTP response with a non-ok status (e.g., 500-level errors).
 *
 * @param {string | URL | Request} url - The URL or Request object to fetch.
 * @param {RequestInit} [options={}] - The options to pass to the fetch call (e.g., method, headers, body).
 * @param {number} [retries=3] - The number of times to retry after the initial failed attempt.
 * @param {number} [baseDelay=1000] - The base delay in milliseconds for the first retry.
 * @returns {Promise<Response>} A promise that resolves with the Response object on success.
 * @throws {Error} Throws the error from the last failed attempt if all retries are exhausted.
 */
async function fetchWithRetry(url, options = {}, retries = 3, baseDelay = 1000) {
  // The loop will run for the initial attempt (i=0) plus the number of retries.
  for (let i = 0; i <= retries; i++) {
    try {
      const response = await fetch(url, options);

      // If the response is successful (status in the 200-299 range), return it.
      if (response.ok) {
        return response;
      }

      // If the response has a non-ok status, it's considered a failure.
      // We throw an error to be caught by the catch block and trigger a retry.
      throw new Error(`Request failed with status ${response.status}`);

    } catch (error) {
      // If this was the last attempt, re-throw the error to the caller.
      if (i === retries) {
        console.error(`All ${retries + 1} attempts failed. Last error:`, error.message);
        throw error;
      }

      // Calculate the delay for the next retry using exponential backoff.
      // Formula: baseDelay * 2^i
      const delay = Math.pow(2, i) * baseDelay;

      // Add "jitter" (a small random variation) to the delay.
      // This helps prevent a "thundering herd" problem where many clients
      // retry at the exact same time after a widespread failure.
      // Here, we add a random value up to 25% of the delay.
      const jitter = delay * 0.25 * Math.random();
      const totalDelay = delay + jitter;

      console.log(
        `Attempt ${i + 1} failed. Retrying in ${Math.round(totalDelay)}ms...`
      );

      // Wait for the calculated delay before the next attempt.
      await wait(totalDelay);
    }
  }
}
