/**
 * A custom error class for HTTP errors.
 * This allows the caller to inspect the response object.
 */
class HTTPError extends Error {
  /**
   * @param {string} message - The error message.
   * @param {Response} response - The raw response object from fetch.
   */
  constructor(message, response) {
    super(message);
    this.name = 'HTTPError';
    this.response = response;
  }
}

/**
 * A helper function to create a delay using a Promise.
 * @param {number} ms - The number of milliseconds to wait.
 * @returns {Promise<void>} A promise that resolves after the specified delay.
 */
const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Fetches a URL with automatic retries on failure, using an exponential backoff strategy.
 *
 * @param {string|URL} url - The URL to fetch.
 * @param {RequestInit} [fetchOptions={}] - The options to pass to the `fetch` call (e.g., method, headers, body).
 * @param {object} [retryOptions={}] - Options for the retry mechanism.
 * @param {number} [retryOptions.retries=3] - The maximum number of retries to attempt after the initial request.
 * @param {number} [retryOptions.retryDelay=1000] - The initial delay in milliseconds before the first retry.
 * @param {number} [retryOptions.backoffFactor=2] - The factor by which the delay should increase for each subsequent retry.
 * @param {function(Error, number): void} [retryOptions.onRetry] - An optional callback function that is called on each retry attempt. It receives the error and the current attempt number.
 * @returns {Promise<Response>} A promise that resolves with the Response object on success.
 * @throws {HTTPError|Error} Throws the last error encountered after all retries have been exhausted.
 *                           It will be an `HTTPError` for status code failures or a generic `Error` for network failures.
 */
async function fetchWithRetry(url, fetchOptions = {}, retryOptions = {}) {
  // Set default values for retry options
  const {
    retries = 3,
    retryDelay = 1000,
    backoffFactor = 2,
    onRetry,
  } = retryOptions;

  let lastError;

  // The loop runs for the initial attempt (attempt 0) plus the number of retries.
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      // For retries (attempt > 0), calculate and wait for the backoff delay.
      if (attempt > 0) {
        // Calculate delay with exponential backoff
        const backoffTime = retryDelay * (backoffFactor ** (attempt - 1));
        // Add jitter to prevent thundering herd problem (e.g., +/- 20% of the delay)
        const jitter = backoffTime * 0.2 * (Math.random() * 2 - 1);
        const totalDelay = backoffTime + jitter;

        console.log(`--- Attempt ${attempt} failed. Retrying in ${Math.round(totalDelay)}ms...`);
        await delay(totalDelay);
      }

      const response = await fetch(url, fetchOptions);

      // If response status is not in the 200-299 range, it's considered an error.
      if (!response.ok) {
        throw new HTTPError(
          `HTTP error! Status: ${response.status} ${response.statusText}`,
          response
        );
      }

      // If the request was successful, return the response and exit the function.
      return response;
    } catch (error) {
      lastError = error;

      // Call the onRetry callback if it's provided.
      if (onRetry) {
        onRetry(error, attempt + 1);
      }

      // If this was the last attempt, break the loop to throw the error.
      if (attempt === retries) {
        break;
      }
    }
  }

  // If the loop completes without a successful response, all retries have failed.
  console.error(`All ${retries + 1} attempts failed. Aborting.`);
  throw lastError; // Throw the last error that was caught.
}

