 * @typedef {import('node-fetch').Response} Response
 */

/**
 * Fetches a resource with a specified number of retries using an exponential backoff strategy.
 *
 * This function wraps the standard `fetch` API to provide resilience against transient
 * network errors or temporary server-side issues.
 *
 * A "failure" is defined as:
 * 1. A network error (e.g., the fetch promise rejects).
 * 2. A server error response (i.e., a status code of 500-599).
 *
 * Client errors (4xx status codes) are not retried as they are generally indicative
 * of a problem with the request itself that won't be resolved by retrying.
 *
 * @param {string | URL} url The URL of the resource to fetch.
 * @param {RequestInit} [options={}] Optional `fetch` options (method, headers, body, etc.).
 * @param {number} [retries=3] The number of times to retry after the initial failed attempt.
 * @param {number} [initialDelay=1000] The initial delay in milliseconds before the first retry. This delay doubles with each subsequent retry.
 * @returns {Promise<Response>} A promise that resolves with the `Response` object on success.
 * @throws {Error} Throws an error if all fetch attempts fail. The error will contain details about the last attempt.
 */
async function fetchWithRetry(url, options = {}, retries = 3, initialDelay = 1000) {
  // The total number of attempts will be the initial one plus the number of retries.
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      if (attempt > 0) {
        // Calculate the delay for this retry.
        // It's exponential: 1s, 2s, 4s, 8s, ...
        // Jitter is added to prevent a "thundering herd" problem, where many clients
        // retry at the exact same time. It randomizes the delay slightly.
        const delay = initialDelay * Math.pow(2, attempt - 1);
        const jitter = delay * 0.2 * Math.random(); // Add up to 20% jitter
        const waitTime = delay + jitter;

        console.log(
          `Attempt ${attempt} failed. Retrying in ${Math.round(waitTime)}ms...`
        );

        // Wait for the calculated delay before the next attempt.
        await new Promise(resolve => setTimeout(resolve, waitTime));
      }

      const response = await fetch(url, options);

      // If the response is successful (status 200-299), return it immediately.
      if (response.ok) {
        return response;
      }

      // Check if the error is a server-side error (5xx). These are retryable.
      if (response.status >= 500 && response.status < 600) {
        // Log the server error and let the loop continue to the next attempt.
        console.error(
          `Attempt ${attempt + 1}/${retries + 1} failed with server error: ${response.status} ${response.statusText}`
        );
        // Continue to the next iteration to retry.
        continue;
      } else {
        // If it's a client-side error (4xx) or other non-5xx error, it's not retryable.
        // We throw an error immediately, as retrying is unlikely to help.
        const error = new Error(
          `Request failed with non-retryable status: ${response.status} ${response.statusText}`
        );
        // Attach the response to the error for further inspection by the caller.
        error.response = response;
        throw error;
      }
    } catch (error) {
      // This block catches network errors (e.g., DNS lookup failure, no connection)
      // or the non-retryable error thrown above.

      // If the error already has a response attached, it was a non-retryable status code.
      // We should re-throw it to exit the retry loop.
      if (error.response) {
        throw error;
      }

      console.error(
        `Attempt ${attempt + 1}/${retries + 1} failed with network error: ${error.message}`
      );

      // If this was the last attempt, we re-throw the error to the caller.
      if (attempt === retries) {
        throw new Error(
          `Failed to fetch from ${url} after ${retries + 1} attempts. Last error: ${error.message}`
        );
      }
      // Otherwise, the loop will continue to the next attempt after the delay.
    }
  }

  // This line should theoretically be unreachable, but it's a safeguard.
  // If the loop completes without success, we throw a final error.
  throw new Error(`Failed to fetch from ${url} after ${retries + 1} attempts.`);
}
