/**
 * A custom error class for HTTP errors, containing the response object.
 * This allows callers to inspect the status code, headers, etc.
 */
class HTTPError extends Error {
  /**
   * @param {string} message - The error message.
   * @param {Response} response - The Response object from the fetch call.
   */
  constructor(message, response) {
    super(message);
    this.name = 'HTTPError';
    this.response = response;
  }
}

/**
 * Fetches a resource with a specified number of retries on failure,
 * using an exponential backoff strategy with jitter.
 *
 * A "failure" is considered to be either a network error (fetch promise rejects)
 * or an HTTP response with a non-ok status (e.g., 4xx or 5xx).
 *
 * @param {string | URL | Request} url - The URL of the resource to fetch.
 * @param {RequestInit} [options={}] - Standard `fetch` options (method, headers, body, etc.).
 * @param {number} [retries=3] - The number of times to retry the fetch on failure. The initial attempt is not counted as a retry.
 * @returns {Promise<Response>} A Promise that resolves to the `Response` object on a successful fetch.
 * @throws {Error | HTTPError} An error if the fetch fails after all retries. The error will be the one from the final attempt.
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  // The base delay in milliseconds for the first retry.
  const baseDelay = 1000;
  // A factor to add randomness (jitter) to the delay.
  const jitterFactor = 0.5;

  let lastError;

  // The loop runs for the initial attempt + the number of retries.
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      if (attempt > 0) {
        // Calculate delay with exponential backoff and jitter
        const exponentialDelay = baseDelay * Math.pow(2, attempt - 1);
        const jitter = exponentialDelay * jitterFactor * (Math.random() - 0.5); // Random value between -0.5 and 0.5
        const delayWithJitter = Math.max(0, exponentialDelay + jitter);

        console.log(
          `Attempt ${attempt} failed. Retrying in ${delayWithJitter.toFixed(2)}ms...`
        );
        // Wait for the calculated delay before the next attempt.
        await new Promise(resolve => setTimeout(resolve, delayWithJitter));
      }

      const response = await fetch(url, options);

      // If the response status is not OK (e.g., 404, 500), it's a failure.
      if (!response.ok) {
        throw new HTTPError(
          `HTTP error! Status: ${response.status}`,
          response
        );
      }

      // If the fetch was successful, return the response immediately.
      console.log(`Attempt ${attempt + 1} succeeded.`);
      return response;

    } catch (error) {
      lastError = error;
      console.error(`Attempt ${attempt + 1} of ${retries + 1} failed:`, error.message);

      // If this was the last attempt, we stop and re-throw the error.
      if (attempt === retries) {
        console.error("All retries failed.");
        throw lastError;
      }
    }
  }
}

