/**
 * Fetches a URL with a specified number of retries using an exponential backoff strategy.
 *
 * This function wraps the native `fetch` API to provide resilience against transient
 * network issues or temporary server-side problems. It will only retry on network
 * errors or on HTTP responses with a 5xx status code. Client-side errors (4xx)
 * will not trigger a retry and will resolve immediately.
 *
 * @param {string | URL | Request} url The resource to fetch. This is the first argument to the `fetch` function.
 * @param {RequestInit} [options={}] An object containing any custom settings that you want to apply to the request.
 * @param {number} [retries=3] The number of times to retry the request *after* the initial attempt fails.
 * @param {number} [baseDelay=1000] The base delay in milliseconds for the first retry. Each subsequent retry will double this delay.
 * @returns {Promise<Response>} A Promise that resolves with the `Response` object if the fetch is successful.
 * @throws {Error} Throws the error from the final attempt if all retries fail.
 */
async function fetchWithRetry(url, options = {}, retries = 3, baseDelay = 1000) {
  let lastError;

  // The loop will run for the initial attempt (i=0) plus the number of retries.
  for (let i = 0; i <= retries; i++) {
    try {
      // On the first attempt, don't log anything special.
      // On subsequent attempts, log the retry attempt.
      if (i > 0) {
        console.log(`Retrying... attempt ${i} of ${retries}`);
      }

      const response = await fetch(url, options);

      // If the response is OK (status in the range 200-299), we're done.
      if (response.ok) {
        return response;
      }

      // If we get a server-side error (5xx), we should retry.
      // We throw an error to be caught by the catch block, which handles the backoff delay.
      if (response.status >= 500 && response.status <= 599) {
        throw new Error(`Server error: ${response.status} ${response.statusText}`);
      }

      // For any other non-ok response (like 4xx client errors), we don't retry.
      // We return the response directly for the caller to handle.
      console.warn(`Client error: ${response.status} ${response.statusText}. Not retrying.`);
      return response;

    } catch (error) {
      // Store the error from this attempt. If all retries fail, this is the error we'll throw.
      lastError = error;

      // If we've used up all our retries, break the loop.
      if (i === retries) {
        break;
      }

      // Calculate the delay for the next retry with exponential backoff.
      // We add a small random "jitter" to the delay to prevent multiple clients
      // from retrying in synchronized waves (thundering herd problem).
      const delayTime = baseDelay * Math.pow(2, i) + Math.random() * 100;

      console.error(`Attempt ${i + 1} failed: ${error.message}. Waiting ${Math.round(delayTime)}ms before retrying.`);

      // Wait for the calculated delay time before the next iteration.
      await new Promise(resolve => setTimeout(resolve, delayTime));
    }
  }

  // If the loop completes without a successful response, throw the last captured error.
  throw new Error(`All ${retries + 1} attempts failed. Last error: ${lastError.message}`);
}
