### Code

```javascript
/**
 * Fetches a resource from a URL with a retry mechanism on failure, using exponential backoff.
 * This function is designed to be resilient to transient network errors and temporary server-side issues.
 *
 * It will retry the request under two conditions:
 * 1. A network error occurs (e.g., the fetch promise rejects).
 * 2. The server responds with a 5xx status code (e.g., 500, 502, 503, 504).
 *
 * It will NOT retry for 4xx client-side errors, as these are typically not temporary.
 *
 * @param {string | URL | Request} url The URL of the resource to fetch.
 * @param {RequestInit} [options={}] The options object for the `fetch` call (e.g., method, headers, body).
 * @param {number} [retries=3] The number of times to retry after the initial failed attempt. A value of 3 means up to 4 total attempts.
 * @param {number} [initialDelay=1000] The initial delay in milliseconds before the first retry.
 * @returns {Promise<Response>} A Promise that resolves to the `Response` object on a successful request.
 * @throws {Error} An error from the last attempt if all retries fail.
 */
async function fetchWithRetry(url, options = {}, retries = 3, initialDelay = 1000) {
  let lastError;

  // The loop runs for the initial attempt (i=0) plus the number of retries.
  for (let i = 0; i <= retries; i++) {
    try {
      if (i > 0) {
        // Calculate the delay with exponential backoff and jitter.
        // Jitter adds a random element to prevent synchronized retries from multiple clients.
        const delay = initialDelay * Math.pow(2, i - 1) + Math.random() * 1000;
        console.log(`--- Attempt ${i} failed. Retrying in ${Math.round(delay)}ms...`);
        // Wait for the calculated delay before the next attempt.
        await new Promise(resolve => setTimeout(resolve, delay));
      }

      const response = await fetch(url, options);

      // If the response is successful (status 200-299), return it immediately.
      if (response.ok) {
        return response;
      }

      // If the server responds with a client-side error (4xx), don't retry.
      // Throw an error to stop the process immediately.
      if (response.status >= 400 && response.status < 500) {
        throw new Error(`Client Error: ${response.status} ${response.statusText}. Will not retry.`);
      }

      // For server-side errors (5xx), we want to retry.
      // We create a new error to be caught by the catch block, which will trigger the retry logic.
      lastError = new Error(`Server Error: ${response.status} ${response.statusText}`);
      // Continue to the next iteration of the loop to retry.

    } catch (error) {
      lastError = error;
      // If the error is a client error we threw intentionally, log it and break the loop.
      if (error.message.startsWith('Client Error')) {
        console.error(error.message);
        break; // Exit the retry loop
      }
      // For network errors or other issues, we'll log and let the loop continue.
    }
  }

  // If all retries have been exhausted, throw the last captured error.
  console.error(`All ${retries + 1} attempts failed.`);
  throw lastError;
}

