### The Code

```javascript
/**
 * A utility function to create a delay.
 * @param {number} ms - The number of milliseconds to wait.
 * @returns {Promise<void>} A promise that resolves after the specified delay.
 */
const wait = (ms) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Fetches a resource with automatic retries on failure, using an exponential backoff strategy with jitter.
 * This is useful for handling transient network errors or temporary server-side issues (like 5xx status codes).
 *
 * A "failure" is defined as:
 * 1. A network error that causes the fetch promise to reject.
 * 2. An HTTP response with a status code that is not "ok" (i.e., not in the 200-299 range).
 *
 * @param {string | URL} url - The URL of the resource to fetch.
 * @param {RequestInit} [options={}] - The options object to pass to the `fetch` call (e.g., method, headers, body).
 * @param {number} [retries=3] - The number of times to retry *after* the initial failed attempt. A value of 3 means up to 4 total attempts.
 * @returns {Promise<Response>} A promise that resolves with the `Response` object on a successful request.
 * @throws {Error} Throws the last encountered error after all retries have been exhausted.
 */
async function fetchWithRetry(url, options = {}, retries = 3) {
  // The base delay in milliseconds for the first retry.
  const baseDelay = 1000;
  // A factor to add randomness (jitter) to the delay, preventing thundering herd problems.
  const jitter = 500;

  // The loop will run for the initial attempt + the number of retries.
  for (let i = 0; i <= retries; i++) {
    try {
      // On the first attempt (i=0), don't log "retrying".
      if (i > 0) {
        console.log(`Attempt ${i} failed. Retrying... (Attempt ${i + 1} of ${retries + 1})`);
      }

      const response = await fetch(url, options);

      // If the response is successful (e.g., status 200-299), return it immediately.
      if (response.ok) {
        return response;
      }

      // If the response has a non-ok status, it's considered a failure.
      // We throw an error to be caught by the catch block, unifying error handling.
      throw new Error(`HTTP error! Status: ${response.status} ${response.statusText}`);

    } catch (error) {
      // If this was the last attempt, re-throw the error to be handled by the caller.
      if (i === retries) {
        console.error(`All ${retries + 1} attempts failed. Last error:`, error.message);
        throw error;
      }

      // Calculate the delay for the next retry with exponential backoff and jitter.
      // Example delays for i = 1, 2, 3:
      // i=1: 1000 * 2^0 + random(500) = ~1000-1500ms
      // i=2: 1000 * 2^1 + random(500) = ~2000-2500ms
      // i=3: 1000 * 2^2 + random(500) = ~4000-4500ms
      const delay = baseDelay * Math.pow(2, i - 1) + Math.random() * jitter;

      // Wait for the calculated delay before the next iteration.
      await wait(delay);
    }
  }
}
```

